e computed group styles."}, {"name": "id", "type": "string", "descriptionKey": "components.avatar_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.avatar_group.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.avatar_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.avatar_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "number", "prop": "max", "labelKey": "components.avatar_group.playground.max", "defaultValue": 4, "labelFallback": "Max visible"}, {"kind": "switch", "prop": "expandOnHover", "labelKey": "components.avatar_group.playground.expand_on_hover", "defaultValue": false, "labelFallback": "Expand on hover"}, {"kind": "switch", "prop": "expandOnClick", "labelKey": "components.avatar_group.playground.expand_on_click", "defaultValue": false, "labelFallback": "Expand on click"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.avatar_group.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('74aaeb37-8ac7-40e8-b521-151e36963adc', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'badge', 'Badge', 'Data Display', NULL, 'mdi-shield-star-outline', 'components.catalog.badge.description', 'Overlay badge for notification counts, status dots and labels, anchored to a wrapped element.', NULL, NULL, 'origam-badge', NULL, 'packages/ds/src/components/Badge/OrigamBadge.vue', 'origam', NULL, NULL, '/stories/?story=components-badge--design', '/docs/components/Badge/OrigamBadge.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.badge.a11y.role_note", "noteFallback": "The badge pill has role=\"status\" with aria-live=\"polite\" and aria-atomic=\"true\". Screen readers announce badge content changes (e.g. new count)."}, {"noteKey": "components.badge.a11y.label_note", "noteFallback": "The label prop (or the translated \"origam.badge\" key) is used as aria-label to describe the badge to screen readers. Pass a meaningful value like \"5 unread notifications\"."}, {"noteKey": "components.badge.a11y.dot_note", "noteFallback": "In dot mode, the content is visually hidden (text-indent: -9999px) but the aria-label still conveys the status to screen readers."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-badge__badge---background-color", "descriptionKey": "components.badge.tokens.background_color", "descriptionFallback": "Default badge pill background."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-badge__badge---border-radius", "descriptionKey": "components.badge.tokens.border_radius", "descriptionFallback": "Full-circle border radius by default."}, {"type": "dimension", "value": "1.25rem", "tokenPath": "--origam-badge__badge---height", "descriptionKey": "components.badge.tokens.height", "descriptionFallback": "Badge pill height (20px)."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-badge__badge---font-size", "descriptionKey": "components.badge.tokens.font_size", "descriptionFallback": "Badge content font size."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-badge--danger---background-color", "descriptionKey": "components.badge.tokens.danger_bg", "descriptionFallback": "Background for error/danger status badges."}, {"type": "duration", "value": "225ms", "tokenPath": "--origam-badge__badge---transition-duration", "descriptionKey": "components.badge.tokens.transition_duration", "descriptionFallback": "Badge position/opacity transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"200\" y=\"50\" width=\"300\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"200\" y=\"50\" width=\"300\" height=\"120\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.5\"/>\n  <rect x=\"230\" y=\"80\" width=\"240\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"115\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot (anchor element)</text>\n  <circle cx=\"475\" cy=\"55\" r=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"475\" y=\"60\" font-size=\"11\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"700\">42</text>\n  <circle cx=\"208\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"208\" y=\"62.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"238\" cy=\"88\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"238\" y=\"92\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"463\" cy=\"43\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"463\" y=\"47\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"350\" y1=\"173\" x2=\"350\" y2=\"190\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"205\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Badge pill uses OrigamTransition (fade by default) for show/hide</text>\n", "code": "<div class=\"origam-badge\">\n  <div class=\"origam-badge__wrapper\">\n    <!-- anchor element -->\n    <slot name=\"default\" />\n\n    <!-- badge pill with show/hide transition -->\n    <origam-transition>\n      <span\n        class=\"origam-badge__badge\"\n        role=\"status\"\n        aria-live=\"polite\"\n        aria-atomic=\"true\"\n        :aria-label=\"label\"\n      >\n        <!-- icon or count content -->\n        <span class=\"origam-badge__content\">{{ content }}</span>\n      </span>\n    </origam-transition>\n  </div>\n</div>", "legend": [{"cls": ".origam-badge", "num": 1, "descriptionKey": "components.badge.anatomy.root", "descriptionFallback": "Root element (<code>display: inline-flex</code>). Receives the <code>tag</code> prop (default <code>&lt;div&gt;</code>). Modifiers: <code>--dot</code>, <code>--floating</code>, <code>--inline</code>."}, {"cls": ".origam-badge__wrapper", "num": 2, "descriptionKey": "components.badge.anatomy.wrapper", "descriptionFallback": "Relative-positioned container that anchors the badge pill. Contains the <code>#default</code> slot (the host element)."}, {"cls": ".origam-badge__badge", "num": 3, "descriptionKey": "components.badge.anatomy.badge", "descriptionFallback": "The visible badge pill (<code>position: absolute</code>). Location computed by <code>useLocation</code>. Content capped at <code>max</code>. Wrapped in <code>OrigamTransition</code> for show/hide animation. Has <code>role=\"status\"</code>, <code>aria-live=\"polite\"</code>, <code>aria-atomic=\"true\"</code>."}], "classes": [{"cls": "origam-badge", "descriptionKey": "components.badge.anatomy.root", "descriptionFallback": "Root inline-flex container."}, {"cls": "origam-badge__wrapper", "descriptionKey": "components.badge.anatomy.wrapper", "descriptionFallback": "Relative-positioned wrapper anchoring the badge."}, {"cls": "origam-badge__badge", "descriptionKey": "components.badge.anatomy.badge", "descriptionFallback": "The visible badge pill (absolute positioned, role=\"status\")."}, {"cls": "origam-badge__content", "descriptionKey": "components.badge.anatomy.content", "descriptionFallback": "Text content span inside the badge pill."}, {"cls": "origam-badge__prepend", "descriptionKey": "components.badge.anatomy.prepend", "descriptionFallback": "Leading icon inside the badge pill."}, {"cls": "origam-badge__append", "descriptionKey": "components.badge.anatomy.append", "descriptionFallback": "Trailing icon inside the badge pill."}], "svgDesc": "Schematic of the Badge component with 3 numbered internal parts.", "svgTitle": "Anatomy