INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bb5b2f57-34ee-41f5-b8e8-117023cbf2d7', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'bracket-match', 'BracketMatch', 'Data Display', NULL, 'mdi-sword-cross', 'components.catalog.bracket_match.description', 'A single match card inside a tournament bracket, showing two competitor rows with optional meta header (status, schedule, watch link) and score columns.', NULL, NULL, 'origam-bracket-match', NULL, 'packages/ds/src/components/Bracket/OrigamBracketMatch.vue', 'origam', NULL, NULL, '/stories/?story=components-bracket--design', '/docs/components/Bracket/OrigamBracketMatch.html', 'bracket', '{"a11y": {"notes": [{"noteKey": "components.bracket_match.a11y.aria_label_note", "noteFallback": "The root has aria-label=\"Match: A versus B\" computed from competitor names."}, {"noteKey": "components.bracket_match.a11y.live_note", "noteFallback": "The \"Watch live\" link opens in a new tab with rel=\"noopener noreferrer\" for security."}, {"noteKey": "components.bracket_match.a11y.status_note", "noteFallback": "Status badges (LIVE, Completed…) are preceded by a colored dot using ::before — no alt text needed as the text label is present."}, {"noteKey": "components.bracket_match.a11y.reduced_motion_note", "noteFallback": "LIVE badge animation (blink + ping) is disabled under prefers-reduced-motion: reduce."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.bracket_match.a11y.key_tab", "actionFallback": "Moves focus into the match card and through each competitor row."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\