INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2a74a943-01f3-49d2-89ee-0fcfec23568f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'bracket-round', 'BracketRound', 'Data Display', NULL, 'mdi-view-column-outline', 'components.catalog.bracket_round.description', 'Renders a single round column (horizontal mode) or row (vertical mode) of a tournament bracket, containing its OrigamBracketMatch cards.', NULL, NULL, 'origam-bracket-round', NULL, 'packages/ds/src/components/Bracket/OrigamBracketRound.vue', 'origam', NULL, NULL, '/stories/?story=components-bracket--design', '/docs/components/Bracket/OrigamBracketRound.html', 'bracket', '{"a11y": {"notes": [{"noteKey": "components.bracket_round.a11y.labelledby_note", "noteFallback": "The round container has aria-labelledby pointing to the title element id when showRoundTitle=true, giving screen readers the round name context."}, {"noteKey": "components.bracket_round.a11y.final_note", "noteFallback": "The final round (last in the bracket) receives the --final modifier class. Consumers can use this for additional ARIA live-region announcements."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.bracket_round.a11y.key_tab", "actionFallback": "Moves focus through each match card within the round."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"480\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"16\" width=\"440\" height=\"188\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"20\" y=\"16\" width=\"440\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"240\" y=\"37\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"monospace\" font-weight=\"600\">SEMI-FINALS</text>\n  <rect x=\"40\" y=\"64\" width=\"400\" height=\"52\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"94\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"monospace\">Match card 1</text>\n  <rect x=\"40\" y=\"136\" width=\"400\" height=\"52\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1\"/>\n  <text x=\"240\" y=\"166\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"monospace\">Match card 2</text>\n  <circle cx=\"28\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"28.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"240\" cy=\"34\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"240\" y=\"38.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"240\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"240\" y=\"94.5\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-bracket-round origam-bracket-round--direction-horizontal\" role=\"group\" aria-labelledby=\"round-1-title\">\n  <h3 id=\"round-1-title\" class=\"origam-bracket-round__title\">Semi-finals</h3>\n  <div class=\"origam-bracket-round__matches\">\n    <!-- #match slot × N -->\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n    <origam-bracket-match class=\"origam-bracket-round__match\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-bracket-round", "num": 1, "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container. role=\"group\" with aria-labelledby pointing to the title. Direction modifier switches to row for vertical mode."}, {"cls": ".origam-bracket-round__title", "num": 2, "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title <h3>. Visible only when showRoundTitle=true. Gets a computed id for aria-labelledby."}, {"cls": ".origam-bracket-round__matches", "num": 3, "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Flex column container for match cards. justify-content: space-around distributes matches evenly. Gap driven by --origam-bracket-round---match-gap."}], "classes": [{"cls": "origam-bracket-round", "descriptionKey": "components.bracket_round.anatomy.root", "descriptionFallback": "Root flex column container."}, {"cls": "origam-bracket-round__title", "descriptionKey": "components.bracket_round.anatomy.title", "descriptionFallback": "Round title heading <h3>."}, {"cls": "origam-bracket-round__matches", "descriptionKey": "components.bracket_round.anatomy.matches", "descriptionFallback": "Match cards container with space-around justification."}, {"cls": "origam-bracket-round__match", "descriptionKey": "components.bracket_round.anatomy.match", "descriptionFallback": "Applied to each OrigamBracketMatch inside the round."}, {"cls": "origam-bracket-round--final", "descriptionKey": "components.bracket_round.anatomy.final", "descriptionFallback": "Added to the last round (index === totalRounds - 1)."}, {"cls": "origam-bracket-round--direction-horizontal", "descriptionKey": "components.bracket_round.anatomy.horizontal", "descriptionFallback": "Flex column layout — matches stack vertically in a column."}, {"cls": "origam-bracket-round--direction-vertical", "descriptionKey": "components.bracket_round.anatomy.vertical", "descriptionFallback": "Flex row layout — matches stack horizontally in a row."}], "svgDesc": "Schematic of the BracketRound column with 3 numbered parts.", "svgTitle": "Anatomy of OrigamBracketRound", "rootClass": "origam-bracket-round", "figcaption": "Anatomy of <code>&lt;origam-bracket-round&gt;</code> — 3 parts: root column, round title heading and match list.", "svgViewBox": "0 0 480 220"}, "cssVars": [{"name": "--origam-bracket-round-title---margin-block-end", "defaultValue": "12px", "descriptionKey": "components.bracket_round.css_vars.title_margin_block_end", "descriptionFallback": "Bottom margin below the round title."}, {"name": "--origam-bracket-round-title---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.bracket_round.css_vars.title_font_size", "descriptionFallback": "Font size of the round title."}, {"name": "--origam-bracket-round-title---font-weight", "defaultValue": "600", "descriptionKey": "components.bracket_round.css_vars.title_font_weight", "descriptionFallback": "Font weight of the round title."}, {"name": "--origam-bracket-round-title---letter-spacing", "defaultValue": "0.04em", "descriptionKey": "components.bracket_round.css_vars.title_letter_spacing", "descriptionFallback": "Letter spacing of the round title."}, {"name": "--origam-bracket-round-title---text-transform", "defaultValue": "uppercase", "descriptionKey": "components.bracket_round.css_vars.title_text_transform", "descriptionFallback": "Text transform of the round title. Default uppercase."}, {"name": "--origam-bracket-round---match-gap", "defaultValue": "24px", "descriptionKey": "components.bracket_round.css_vars.match_gap", "descriptionFallback": "Gap between match cards in the round."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.bracket_round.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "neutral", "value": "neutral"}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "ghost", "value": "ghost"}, {"label": "success", "value": "success"}, {"label": "warning", "value": "warning"}, {"label": "danger", "value": "danger"}, {"label": "info", "value": "info"}], "labelKey": "components.bracket_round.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "showRoundTitle", "labelKey": "components.bracket_round.playground.show_round_title", "defaultValue": true, "labelFallback": "Show Round Title"}, {"kind": "switch", "prop": "showScores", "labelKey": "components.bracket_round.playground.show_scores", "defaultValue": true, "labelFallback": "Show Scores"}, {"kind": "switch", "prop": "showSeed", "labelKey": "components.bracket_round.playground.show_seed", "defaultValue": false, "labelFallback": "Show Seed"}, {"kind": "switch", "prop": "interactive", "labelKey": "components.bracket_round.playground.interactive", "defaultValue": true, "labelFallback": "Interactive"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "DIRECTION.HORIZONTAL", "value": "DIRECTION.HORIZONTAL"}, {"label": "horizontal", "value": "horizontal"}, {"label": "DIRECTION.VERTICAL", "value": "DIRECTION.VERTICAL"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.bracket_round.playground.direction", "defaultValue": "", "labelFallback": "Direction"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4ba7168d-7c43-446a-8da7-c9cbeeed9bdf', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'breadcrumb', 'Breadcrumb', 'Navigation', NULL, 'mdi-dots-horizontal', 'components.catalog.breadcrumb.description', 'Hierarchical navigation trail rendered as a <nav> landmark with an ordered list of items and configurable dividers.', NULL, NULL, 'origam-breadcrumb', NULL, 'packages/ds/src/components/Breadcrumb/OrigamBreadcrumb.vue', 'origam', NULL, NULL, '/stories/?story=components-breadcrumb--design', '/docs/components/Breadcrumb/OrigamBreadcrumb.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.breadcrumb.a11y.aria_label", "noteFallback": "The root <nav> receives aria-label=\"Breadcrumb\" from the useLocale translation (key: origam.breadcrumb.ariaLabel)."}, {"noteKey": "components.breadcrumb.a11y.aria_current", "noteFallback": "The last item is automatically set to aria-current=\"page\" via the isActive prop on OrigamBreadcrumbItem."}, {"noteKey": "components.breadcrumb.a11y.divider_hidden", "noteFallback": "OrigamBreadcrumbDivider is aria-hidden — the separators are purely presentational and not read by screen readers."}, {"noteKey": "components.breadcrumb.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to the root for auto contrast when a custom color is set."}, {"noteKey": "components.breadcrumb.a11y.disabled_opacity", "noteFallback": "Disabled items receive opacity-50 and pointer-events: none without the native disabled attribute (which does not apply to anchors)."}], "roles": ["navigation", "list", "listitem"], "keyboard"