ght=\"72\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"180\" y=\"88\" width=\"248\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"304\" y=\"105\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label / #default slot</text>\n  <rect x=\"472\" y=\"66\" width=\"76\" height=\"72\" rx=\"3\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <rect x=\"484\" y=\"80\" width=\"52\" height=\"44\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"510\" y=\"106\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <circle cx=\"36\" cy=\"52\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"56.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"568\" cy=\"52\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"568\" y=\"56.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"578\" y1=\"50\" x2=\"612\" y2=\"36\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"616\" y=\"38\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">abs · opacity 0</text>\n  <circle cx=\"568\" cy=\"152\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"568\" y=\"156.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"578\" y1=\"152\" x2=\"612\" y2=\"152\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"616\" y=\"155\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-style=\"italic\">abs · décoratif</text>\n  <circle cx=\"300\" cy=\"159\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"300\" y=\"163\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"300\" y1=\"168\" x2=\"300\" y2=\"184\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"300\" y=\"196\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">loader-line | loader-circular</text>\n  <circle cx=\"56\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"68\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"98\" cy=\"72\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"98\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"304\" cy=\"72\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"304\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <circle cx=\"510\" cy=\"72\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"510\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">8</text>\n  <line x1=\"46\" y1=\"46\" x2=\"84\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"88\" y=\"30\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-btn</text>\n  <line x1=\"66\" y1=\"60\" x2=\"96\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"100\" y=\"20\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">__loader · inline-grid 3col</text>\n  <text x=\"350\" y=\"245\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② ③ ④ = calques absolus, invisibles au repos ou conditionnels</text>\n", "code": "<!-- root: resolves to <button> or <a> via useLink -->\n<component :is=\"link.tag\" class=\"origam-btn\">\n  <!-- interaction overlay (hover/active ripple background) -->\n  <span class=\"origam-btn__overlay\" />\n  <!-- underlay reserved for future use -->\n  <span class=\"origam-btn__underlay\" />\n\n  <!-- circular/line progress loader (visible only when loading=true) -->\n  <origam-progress class=\"origam-btn__progress\" />\n\n  <!-- inner layout grid: prepend | content | append -->\n  <origam-loader class=\"origam-btn__loader\">\n    <!-- prepend slot: icon or avatar before label -->\n    <span class=\"origam-btn__prepend\">\n      <slot name=\"prepend\" />\n    </span>\n\n    <!-- main label / icon-only content -->\n    <span class=\"origam-btn__content\">\n      <slot name=\"default\" />\n    </span>\n\n    <!-- append slot: icon or avatar after label -->\n    <span class=\"origam-btn__append\">\n      <slot name=\"append\" />\n    </span>\n  </origam-loader>\n</component>", "legend": [{"cls": ".origam-btn", "num": 1, "descriptionKey": "components.btn.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;button&gt;</code> by default, <code>&lt;a&gt;</code> when <code>href</code> is set."}, {"cls": ".origam-btn__overlay", "num": 2, "descriptionKey": "components.btn.anatomy.overlay", "descriptionFallback": "Absolute scrim. <code>opacity: 0</code> → 0.12 hover → 0.2 active. Driven by <code>--origam-btn__overlay---opacity</code>."}, {"cls": ".origam-btn__underlay", "num": 3, "descriptionKey": "components.btn.anatomy.underlay", "descriptionFallback": "Absolute decorative layer. <code>inset: 0 / pointer-events: none</code>. Reserved for tonal/ghost compositing."}, {"cls": ".origam-btn__progress", "num": 4, "descriptionKey": "components.btn.anatomy.progress", "descriptionFallback": "Rendered only when <code>loading</code> is active. Modes: linear strip (<code>loader-line</code>) or circular spinner (<code>loader-circular</code>)."}, {"cls": ".origam-btn__loader", "num": 5, "descriptionKey": "components.btn.anatomy.loader", "descriptionFallback": "<code>inline-grid</code>, 3 columns: max-content / auto / max-content. In <code>--stacked</code> mode switches to 3 rows."}, {"cls": ".origam-btn__prepend", "num": 6, "descriptionKey": "components.btn.anatomy.prepend", "descriptionFallback": "Leading slot. Renders <code>prependIcon</code> or <code>prependAvatar</code>, or the <code>#prepend</code> slot. <code>v-if=\"hasPrepend\"</code>."}, {"cls": ".origam-btn__content", "num": 7, "descriptionKey": "components.btn.anatomy.content", "descriptionFallback": "Label zone. Contains the <code>#default</code> slot. Hidden via <code>opacity: 0</code> in <code>loader-circular</code> mode."}, {"cls": ".origam-btn__append", "num": 8, "descriptionKey": "components.btn.anatomy.append", "descriptionFallback": "Trailing slot. Renders <code>appendIcon</code> or <code>appendAvatar</code>, or the <code>#append</code> slot. <code>v-if=\"hasAppend\"</code>."}], "classes": [{"cls": "origam-btn", "descriptionKey": "components.btn.anatomy.root", "descriptionFallback": "Root element. Renders as <button> by default, or <a> when href/to is set."}, {"cls": "origam-btn__overlay", "descriptionKey": "components.btn.anatomy.overlay", "descriptionFallback": "Interaction overlay layer. Opacity animates on hover/active to show the surface tint."}, {"cls": "origam-btn__underlay", "descriptionKey": "components.btn.anatomy.underlay", "descriptionFallback": "Reserved underlay layer (future use). Positioned identically to __overlay."}, {"cls": "origam-btn__progress", "descriptionKey": "components.btn.anatomy.progress", "descriptionFallback": "OrigamProgress spinner injected when loading=true. Positioned absolutely over the content."}, {"cls": "origam-btn__loader", "descriptionKey": "components.btn.anatomy.loader", "descriptionFallback": "Inner grid container: grid-template-areas \"prepend content append\". Hosts all visible children."}, {"cls": "origam-btn__prepend", "descriptionKey": "components.btn.anatomy.prepend", "descriptionFallback": "Prepend area: grid-area prepend. Hosts prependIcon, prependAvatar, or the prepend slot."}, {"cls": "origam-btn__content", "descriptionKey": "components.btn.anatomy.content", "descriptionFallback": "Label/icon area: grid-area content. Contains the default slot text or icon-only content."}, {"cls": "origam-btn__append", "descriptionKey": "components.btn.anatomy.append", "descriptionFallback": "Append area: grid-area append. Hosts appendIcon, appendAvatar, or the append slot."}], "svgDesc": "Schematic of the Btn component with 8 numbered internal parts.", "svgTitle": "Anatomy of OrigamBtn", "rootClass": "origam-btn", "figcaption": "Anatomy of <code>&lt;origam-btn&gt;</code> — 8 internal parts, each numbered per BEM class. Absolute layers (overlay ②, underlay ③, progress ④) sit over the root; the loader grid ⑤ stacks prepend / content / append in a 3-column inline-grid.", "svgViewBox": "0 0 700 260"}, "cssVars": [{"name": "--origam-btn---background-color", "defaultValue": "{color.action.secondary.bg}", "descriptionKey": "components.btn.css_vars.background_color", "descriptionFallback": "Default button background color. Resolves to the secondary action surface."}, {"name": "--origam-btn---color", "defaultValue": "{color.action.secondary.fg}", "descriptionKey": "components.btn.css_vars.color", "descriptionFallback": "Default foreground (text/icon) color."}, {"name": "--origam-btn---height", "defaultValue": "36px", "descriptionKey": "components.btn.css_vars.height", "descriptionFallback": "Button height. Overridden per size class (x-small: 20px … x-large: 52px)."}, {"name": "--origam-btn---font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.btn.css_vars.font_size", "descriptionFallback": "Button font size. Overridden per size variant."}, {"name": "--origam-btn---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.btn.css_vars.font_weight", "descriptionFallback": "Button font weight."}, {"name": "--origam-btn---letter-spacing", "defaultValue": "{font.letterSpacing.widest}", "descriptionKey": "components.btn.css_vars.letter_spacing", "descriptionFallback": "Letter spacing applied to button label."}, {"name": "--origam-btn---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.btn.css_vars.border_radius", "descriptionFallback": "Border radius. Overridden by rounded prop and icon mode."}, {"name": "--origam-btn---border-radius-icon", "defaultValue": "{radius.full}", "descriptionKey": "components.btn.css_vars.border_radius_icon", "descriptionFallback": "Border radius when icon=true (full circle)."}, {"name": "--origam-btn---opacity", "defaultValue": "1", "descriptionKey": "components.btn.css_vars.opacity", "descriptionFallback": "Button opacity. Set to --origam-btn---opacity-disabled (0.5) when disabled."}, {"name": "--origam-btn---box-shadow-elevated", "defaultValue": "{shadow.md}", "descriptionKey": "components.btn.css_vars.box_shadow_elevated", "descriptionFallback": "Box shadow used by variant=\"elevated\"."}, {"name": "--origam-btn---transition-duration", "defaultValue": "{motion.duration.slow}", "descriptionKey": "components.btn.css_vars.transition_duration", "descriptionFallback": "Transition duration for shadow, transform, opacity and background."}, {"name": "--origam-btn---density", "defaultValue": "0px", "descriptionKey": "components.btn.css_vars.density", "descriptionFallback": "Density offset applied to height and min-width. compact: -8px, comfortable: +8px."}, {"name": "--origam-btn__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.btn.css_vars.overlay_opacity", "descriptionFallback": "Overlay opacity. Animates on hover (0.12) and active (0.2)."}], "exposed": [{"name": "group", "type": "GroupItemProvide | null", "descriptionKey": "components.btn.exposed.group", "descriptionFallback": "Group item context when the button is inside a BtnToggle or BtnGroup. Null otherwise."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.btn.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component (e.g. OrigamProgress inside the loader slot)."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.btn.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed btnStyles. Used by OrigamDefaultsProvider to inject styles."}, {"name": "id", "type": "string", "descriptionKey": "components.btn.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance (used by useStyle to scope injected CSS)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.btn.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.btn.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.btn.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.btn.playground.color", "defaultValue": "primary", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "variant", "options": [{"label": "elevated", "value": "elevated"}, {"label": "flat", "value": "flat"}, {"label": "tonal", "value": "tonal"}, {"label": "outlined", "value": "outlined"}, {"label": "text", "value": "text"}, {"label": "plain", "value": "plain"}, {"label": "ghost", "value": "ghost"}], "labelKey": "components.btn.playground.variant", "defaultValue": "elevated", "labelFallback": "Variant"}, {"kind": "select", "prop": "size", "options": [{"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.btn.playground.size", "defaultValue": "default", "labelFallback": "Size"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "0", "value": "0"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "pill", "value": "pill"}], "labelKey": "components.btn.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-download", "value": "mdi-download"}, {"label": "mdi-arrow-right", "value": "mdi-arrow-right"}], "labelKey": "components.btn.playground.prepend_icon", "defaultValue": "", "labelFallback": "Prepend icon"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.btn.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "loading", "labelKey": "components.btn.playground.loading", "defaultValue": false, "labelFallback": "Loading"}], "defaultSlotContent": "Click me"}, "previewVariants": [{"label": "default", "props": {"color": "primary", "variant": "elevated", "prependIcon": "mdi-arrow-down"}, "slotContent": "Default"}, {"label": "outlined", "props": {"color": "primary", "variant": "outlined"}, "slotContent": "Outlined"}, {"label": "tonal", "props": {"color": "primary", "variant": "tonal"}, "slotContent": "Tonal"}, {"label": "ghost", "props": {"color": "primary", "variant": "ghost"}, "slotContent": "Ghost"}, {"label": "disabled", "props": {"color": "primary", "variant": "elevated", "disabled": true}, "ariaLabel": "Disabled button", "slotContent": "Disabled"}, {"label": "loading", "props": {"color": "primary", "loading": true, "variant": "elevated"}, "ariaLabel": "Loading button", "slotContent": "Loading"}, {"label": "rounded pill", "props": {"color": "primary", "rounded": "pill", "variant": "elevated"}, "slotContent": "Pill"}]}', true, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2771475c-5a4d-40e5-bc32-60186dce87b5', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'btn-group', 'BtnGroup', 'Form & Input', NULL, 'mdi-format-horizontal-align-center', 'components.catalog.btn_group.description', 'Groups Btn elements into a connected segmented control. Propagates density, color and hover/active state to child buttons via OrigamDefaultsProvider.', NULL, NULL, 'origam-btn-group', NULL, 'packages/ds/src/components/Btn/OrigamBtnGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-btn--design', '/docs/components/Btn/OrigamBtn.html', 'btn', '{"a11y": {"notes": [{"noteKey": "components.btn_group.a11y.role_group", "noteFallback": "The root element always carries role=\"group\". Consider adding aria-label or aria-labelledby to describe the group purpose (e.g. \"Text alignment\")."}, {"noteKey": "components.btn_group.a11y.border_management", "noteFallback": "Child buttons inside the group share adjacent borders (border-inline-end suppressed on non-last, border-inline-start on non-first). This ensures no double borders visually while keeping each button individually focusable."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.btn_group.a11y.key_tab", "actionFallback": "Moves focus through each button in the group sequentially."}, {"key": "Enter / Space", "actionKey": "components.btn_group.a11y.key_activate", "actionFallback": "Activates the focused button."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-btn-group---border-radius", "descriptionKey": "components.btn_group.tokens.border_radius", "descriptionFallback": "Default border radius for the group container."}, {"type": "dimension", "value": "var(--origam-border__width---0)", "tokenPath": "--origam-btn-group---border-width", "descriptionKey": "components.btn_group.tokens.border_width", "descriptionFallback": "Default border width (none until border prop is set)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"25\" width=\"620\" height=\"70\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"35\" width=\"180\" height=\"50\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"140\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-btn</text>\n  <rect x=\"230\" y=\"35\" width=\"180\" height=\"50\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <text x=\"320\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-btn</text>\n  <rect x=\"410\" y=\"35\" width=\"180\" height=\"50\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\"/>\n  <text x=\"500\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-btn</text>\n  <circle cx=\"48\" cy=\"33\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"37.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"58\" cy=\"37\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"58\" y=\"41.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"240\" cy=\"37\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"240\" y=\"41.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"58\" y1=\"33\" x2=\"110\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"114\" y=\"8\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-btn-group</text>\n  <line x1=\"250\" y1=\"35\" x2=\"250\" y2=\"12\" stroke=\"var(--origam-color__action--primary---bgHover, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"252\" y=\"10\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">border-inline-end (divided)</text>\n", "code": "<!-- root: <div role=\"group\"> -->\n<div class=\"origam-btn-group\">\n  <!-- OrigamDefaultsProvider propagates group defaults to children -->\n  <origam-defaults-provider :defaults=\"slotDefaults\">\n    <slot name=\"default\">\n      <!-- items-driven path -->\n      <origam-btn v-for=\"item in items\" v-bind=\"item\" />\n    </slot>\n  </origam-defaults-provider>\n</div>", "legend": [{"cls": ".origam-btn-group", "num": 1, "descriptionKey": "components.btn_group.anatomy.root", "descriptionFallback": "Root element (default: <code>&lt;div&gt;</code>, role=\"group\"). inline-flex, overflow: hidden, vertical-align: middle. Carries border, elevation and rounding classes. Child buttons are forced border-radius: 0 and box-shadow: none via :deep."}, {"cls": ".origam-btn-group--divided", "num": 2, "descriptionKey": "components.btn_group.anatomy.divided_modifier", "descriptionFallback": "Modifier applied when <code>divided=true</code>. Adds a <code>border-inline-end</code> between non-last child buttons."}, {"cls": "(origam-btn children)", "num": 3, "descriptionKey": "components.btn_group.anatomy.children", "descriptionFallback": "Child <code>&lt;origam-btn&gt;</code> elements. Receive density, color, bgColor, hover, active defaults from the group via OrigamDefaultsProvider. Individual children can override these defaults."}], "classes": [{"cls": "origam-btn-group", "descriptionKey": "components.btn_group.anatomy.root", "descriptionFallback": "Root container. inline-flex, overflow: hidden, max-width: 100%, min-height: calc(height + density)."}, {"cls": "origam-btn-group--divided", "descriptionKey": "components.btn_group.anatomy.divided_modifier", "descriptionFallback": "Shows border-inline-end on all non-last child buttons."}, {"cls": "origam-btn-group--density-default", "descriptionKey": "components.btn_group.anatomy.density_default", "descriptionFallback": "Density default (0px offset)."}, {"cls": "origam-btn-group--density-compact", "descriptionKey": "components.btn_group.anatomy.density_compact", "descriptionFallback": "Density compact (−8px height offset)."}, {"cls": "origam-btn-group--density-comfortable", "descriptionKey": "components.btn_group.anatomy.density_comfortable", "descriptionFallback": "Density comfortable (+8px height offset)."}], "svgDesc": "Schematic of the BtnGroup component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamBtnGroup", "rootClass": "origam-btn-group", "figcaption": "Anatomy of <code>&lt;origam-btn-group&gt;</code> — root container ① (role=\"group\"), OrigamDefaultsProvider ② wrapping child buttons ③. With <code>divided</code>, a <code>border-inline-end</code> separates adjacent buttons.", "svgViewBox": "0 0 700 120"}, "cssVars": [{"name": "--origam-btn-group---height", "defaultValue": "36px", "descriptionKey": "components.btn_group.css_vars.height", "descriptionFallback": "Reference height used to compute min-height with density offset."}, {"name": "--origam-btn-group---density", "defaultValue": "0px", "descriptionKey": "components.btn_group.css_vars.density", "descriptionFallback": "Density offset. comfortable: +8px, default: 0px, compact: −8px."}, {"name": "--origam-btn-group---border-radius", "defaultValue": "4px", "descriptionKey": "components.btn_group.css_vars.border_radius", "descriptionFallback": "Group container border-radius. Overridden by rounded modifier classes."}, {"name": "--origam-btn-group---border-width", "defaultValue": "0", "descriptionKey": "components.btn_group.css_vars.border_width", "descriptionFallback": "Group border width. Set to \"thin\" when border=true."}, {"name": "--origam-btn-group---border-style", "defaultValue": "solid", "descriptionKey": "components.btn_group.css_vars.border_style", "descriptionFallback": "Group border style."}, {"name": "--origam-btn-group---border-color", "defaultValue": "currentColor", "descriptionKey": "components.btn_group.css_vars.border_color", "descriptionFallback": "Group border color (currentColor by default)."}, {"name": "--origam-btn-group---background-color", "defaultValue": "transparent", "descriptionKey": "components.btn_group.css_vars.background_color", "descriptionFallback": "Group background color."}, {"name": "--origam-btn-group---color", "defaultValue": "inherit", "descriptionKey": "components.btn_group.css_vars.color", "descriptionFallback": "Group foreground color (inherited by default)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.btn_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components. Used by OrigamBtnToggle to proxy group props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.btn_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed btnGroupStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.btn_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.btn_group.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.btn_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.btn_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "divided", "labelKey": "components.btn_group.playground.divided", "defaultValue": false, "labelFallback": "Divided"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}], "labelKey": "components.btn_group.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "pill", "value": "pill"}], "labelKey": "components.btn_group.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "border", "labelKey": "components.btn_group.playground.border", "defaultValue": false, "labelFallback": "Border"}, {"kind": "select", "prop": "density", "options": [{"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.btn_group.playground.density", "defaultValue": "default", "labelFallback": "Density"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0981fb9f-fa18-4b37-a1a9-2c12ec7ebdf3', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'btn-toggle', 'BtnToggle', 'Form & Input', NULL, 'mdi-toggle-switch-outline', 'components.catalog.btn_toggle.description', 'Single or multi-select toggle group of Btn elements. Wraps OrigamBtnGroup and adds selection state via useGroup (supports v-model).', NULL, NULL, 'origam-btn-toggle', NULL, 'packages/ds/src/components/Btn/OrigamBtnToggle.vue', 'origam', NULL, NULL, '/stories/?story=components-btn--design', '/docs/components/Btn/OrigamBtn.html', 'btn', '{"a11y": {"notes": [{"noteKey": "components.btn_toggle.a11y.role_group", "noteFallback": "Inherits role=\"group\" from OrigamBtnGroup. Add aria-label to describe the toggle purpose (e.g. \"Text alignment controls\")."}, {"noteKey": "components.btn_toggle.a11y.aria_pressed", "noteFallback": "Each selected child OrigamBtn should communicate its state via aria-pressed=\"true\". Ensure child buttons pass their active state correctly."}, {"noteKey": "components.btn_toggle.a11y.mandatory", "noteFallback": "When mandatory=true, at least one button is always selected. Consider communicating this constraint to assistive technology users via group description."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.btn_toggle.a11y.key_tab", "actionFallback": "Moves focus through each toggle button."}, {"key": "Enter / Space", "actionKey": "components.btn_toggle.a11y.key_activate", "actionFallback": "Toggles the selection state of the focused button."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-btn-group---border-radius", "descriptionKey": "components.btn_toggle.tokens.border_radius", "descriptionFallback": "Default border radius for the toggle container."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"20\" width=\"620\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"50\" y=\"30\" width=\"600\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bg, rgba(124,58,237,0.8))\"/>\n  <text x=\"145\" y=\"64\" font-size=\"11\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">selected</text>\n  <rect x=\"230\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"315\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">unselected</text>\n  <rect x=\"400\" y=\"38\" width=\"170\" height=\"44\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"485\" y=\"64\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">unselected</text>\n  <circle cx=\"48\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"58\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"58\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"68\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"68\" y=\"44.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <line x1=\"58\" y1=\"26\" x2=\"120\" y2=\"8\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"124\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-btn-toggle</text>\n", "code": "<!-- root: thin wrapper, adds .origam-btn-toggle class -->\n<origam-btn-group class=\"origam-btn-toggle\" v-bind=\"btnGroupProps\">\n  <template #default>\n    <!-- default slot exposes group navigation API -->\n    <slot v-bind=\"{ items, isSelected, next, prev, select, selected }\" />\n  </template>\n  <template #item=\"{ item, index }\">\n    <slot name=\"item\" v-bind=\"{ item, index }\" />\n  </template>\n</origam-btn-group>", "legend": [{"cls": ".origam-btn-toggle", "num": 1, "descriptionKey": "components.btn_toggle.anatomy.root", "descriptionFallback": "Root modifier class added on top of <code>.origam-btn-group</code>. OrigamBtnToggle is a thin wrapper that adds selection state (useGroup) and exposes the group navigation API (next/prev/select)."}, {"cls": ".origam-btn-group", "num": 2, "descriptionKey": "components.btn_toggle.anatomy.group", "descriptionFallback": "The proxied <code>&lt;origam-btn-group&gt;</code> with all group-level props forwarded via filterProps. Provides the visual container (border, elevation, rounded, overflow: hidden)."}, {"cls": "(origam-btn children)", "num": 3, "descriptionKey": "components.btn_toggle.anatomy.children", "descriptionFallback": "Child <code>&lt;origam-btn&gt;</code> elements with a <code>value</code> prop. isSelected state from useGroup drives the active styling on the matching button."}], "classes": [{"cls": "origam-btn-toggle", "descriptionKey": "components.btn_toggle.anatomy.root", "descriptionFallback": "Root class added alongside origam-btn-group. No additional styles — purely a BEM identifier for the toggle variant."}], "svgDesc": "Schematic of the BtnToggle component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamBtnToggle", "rootClass": "origam-btn-toggle", "figcaption": "Anatomy of <code>&lt;origam-btn-toggle&gt;</code> — outer toggle shell ① (adds <code>.origam-btn-toggle</code> modifier), inner <code>&lt;origam-btn-group&gt;</code> ② rendering child buttons ③. Selected button receives active state from useGroup.", "svgViewBox": "0 0 700 120"}, "cssVars": [{"name": "--origam-btn-group---border-radius", "defaultValue": "4px", "descriptionKey": "components.btn_toggle.css_vars.border_radius", "descriptionFallback": "Inherited from BtnGroup. Border-radius of the toggle container."}, {"name": "--origam-btn-group---density", "defaultValue": "0px", "descriptionKey": "components.btn_toggle.css_vars.density", "descriptionFallback": "Inherited from BtnGroup. Density offset for min-height."}], "exposed": [{"name": "next", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.next", "descriptionFallback": "Selects the next button in the group (wraps around)."}, {"name": "prev", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.prev", "descriptionFallback": "Selects the previous button in the group (wraps around)."}, {"name": "select", "type": "(id: string | number, value: boolean) => void", "descriptionKey": "components.btn_toggle.exposed.select", "descriptionFallback": "Programmatically select or deselect a button by its value id."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.btn_toggle.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.btn_toggle.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed btnToggleStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.btn_toggle.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.btn_toggle.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.btn_toggle.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "multiple", "labelKey": "components.btn_toggle.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "mandatory", "labelKey": "components.btn_toggle.playground.mandatory", "defaultValue": false, "labelFallback": "Mandatory"}, {"kind": "switch", "prop": "divided", "labelKey": "components.btn_toggle.playground.divided", "defaultValue": false, "labelFallback": "Divided"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}], "labelKey": "components.btn_toggle.playground.color", "defaultValue": "", "labelFallback": "Color"}, {"kind": "switch", "prop": "border", "labelKey": "components.btn_toggle.playground.border", "defaultValue": true, "labelFallback": "Border"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "pill", "value": "pill"}], "labelKey": "components.btn_toggle.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bba2fbc9-93c5-4083-a2ab-d35c607eace0', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'calendar', 'Calendar', 'Data Display', NULL, 'mdi-calendar', 'components.catalog.calendar.description', 'Full-featured calendar with month, week, day and agenda views, drag-select, event colouring by category and v-model bindings.', NULL, NULL, 'origam-calendar', NULL, 'packages/ds/src/components/Calendar/OrigamCalendar.vue', 'origam', NULL, NULL, '/stories/?story=components-calendar--design', '/docs/components/Calendar/OrigamCalendar.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.calendar.a11y.application_role", "noteFallback": "role=\"application\" is used on the root to indicate rich interactive content to assistive technologies. The @keydown handler manages arrow navigation."}, {"noteKey": "components.calendar.a11y.grid_semantics", "noteFallback": "Month view uses role=\"grid\" / role=\"row\" / role=\"gridcell\" for full grid semantics. Week numbers use role=\"rowheader\"."}, {"noteKey": "components.calendar.a11y.event_aria_label", "noteFallback": "Each event button has an aria-label describing the event title and time range."}, {"noteKey": "components.calendar.a11y.disabled_dates", "noteFallback": "Disabled day cells receive aria-disabled=\"true\". Drag-select is prevented on disabled cells."}, {"noteKey": "components.calendar.a11y.today_cell", "noteFallback": "Today''s cell is identified visually with a primary background tint. Consumers should add aria-label=\"Today\" via the #day slot for full AT support."}], "roles": ["application", "toolb