ss_vars.day_cell_height", "descriptionFallback": "Month-view day cell height."}, {"name": "--origam-calendar__day-cell---bg-color-today", "defaultValue": "{color.action.primary.bgSubtle}", "descriptionKey": "components.calendar.css_vars.today_bg", "descriptionFallback": "Background of today''s cell."}, {"name": "--origam-calendar__day-cell---bg-color-weekend", "defaultValue": "{color.surface.sunken}", "descriptionKey": "components.calendar.css_vars.weekend_bg", "descriptionFallback": "Background of weekend cells when weekendHighlight=true."}, {"name": "--origam-calendar__event---bg-color-default", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.calendar.css_vars.event_bg", "descriptionFallback": "Default event chip background."}, {"name": "--origam-calendar__toolbar---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.calendar.css_vars.toolbar_bg", "descriptionFallback": "Toolbar background."}, {"name": "--origam-calendar__timeline---slot-height", "defaultValue": "32px", "descriptionKey": "components.calendar.css_vars.slot_height", "descriptionFallback": "Height per timeline slot row (proportional to slotDuration)."}], "exposed": [{"name": "visibleDateRange", "type": "ComputedRef<{ start: Date; end: Date }>", "descriptionKey": "components.calendar.exposed.visible_date_range", "descriptionFallback": "Start and end Date of the currently rendered period (useful for fetching remote events)."}, {"name": "expandedEvents", "type": "ComputedRef<IEvent[]>", "descriptionKey": "components.calendar.exposed.expanded_events", "descriptionFallback": "Events after recurring expansion within the visible date range."}, {"name": "navigate", "type": "(direction: TCalendarNavigate) => void", "descriptionKey": "components.calendar.exposed.navigate", "descriptionFallback": "Programmatically navigate: \"prev\", \"next\" or \"today\"."}, {"name": "setView", "type": "(view: TCalendarView) => void", "descriptionKey": "components.calendar.exposed.set_view", "descriptionFallback": "Programmatically switch the view mode."}], "playground": {"controls": [{"kind": "select", "prop": "view", "options": [{"label": "month", "value": "month"}, {"label": "week", "value": "week"}, {"label": "day", "value": "day"}, {"label": "agenda", "value": "agenda"}], "labelKey": "components.calendar.playground.view", "defaultValue": "month", "labelFallback": "View"}, {"kind": "select", "prop": "firstDayOfWeek", "options": [{"label": "Monday (1)", "value": 1}, {"label": "Sunday (0)", "value": 0}], "labelKey": "components.calendar.playground.first_day_of_week", "defaultValue": 1, "labelFallback": "First day of week"}, {"kind": "switch", "prop": "weekendHighlight", "labelKey": "components.calendar.playground.weekend_highlight", "defaultValue": true, "labelFallback": "Weekend highlight"}, {"kind": "switch", "prop": "showWeekNumbers", "labelKey": "components.calendar.playground.show_week_numbers", "defaultValue": false, "labelFallback": "Week numbers"}, {"kind": "switch", "prop": "selectable", "labelKey": "components.calendar.playground.selectable", "defaultValue": true, "labelFallback": "Drag-select"}, {"kind": "select", "prop": "timeFormat", "options": [{"label": "24h", "value": "24h"}, {"label": "12h", "value": "12h"}], "labelKey": "components.calendar.playground.time_format", "defaultValue": "24h", "labelFallback": "Time format"}]}, "previewVariants": [{"label": "month view", "props": {"view": "month"}}, {"label": "week view", "props": {"view": "week"}}, {"label": "agenda view", "props": {"view": "agenda"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f0423bd2-0870-44bc-b4c1-fbb71f0cb9b8', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'card', 'Card', 'Surface', NULL, 'mdi-card-outline', 'components.catalog.card.description', 'Versatile surface container with title, subtitle, image asset, text body, footer slots, link support, loading states and ripple interaction.', NULL, NULL, 'origam-card', NULL, 'packages/ds/src/components/Card/OrigamCard.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.card.a11y.disabled_tabindex", "noteFallback": "When disabled=true, tabindex=\"-1\" is set to remove the card from the tab order."}, {"noteKey": "components.card.a11y.link_semantics", "noteFallback": "When href or to is set, the card root renders as <a> with proper link semantics. The ripple v-ripple directive triggers on the native click event."}, {"noteKey": "components.card.a11y.focus_visible", "noteFallback": "Focus-visible outline is applied via :focus-visible in the component SCSS — visible for keyboard navigation, not mouse clicks."}, {"noteKey": "components.card.a11y.overlay_hidden", "noteFallback": "The __overlay and __underlay spans are aria-hidden (inert layers)."}, {"noteKey": "components.card.a11y.v_contrast", "noteFallback": "The v-contrast directive is applied to ensure accessible foreground/background contrast when color is set."}, {"noteKey": "components.card.a11y.loader", "noteFallback": "The OrigamProgress inside the loader slot has role=\"progressbar\". OrigamSkeleton is aria-hidden (decorative)."}], "roles": ["article", "link", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.card.a11y.key_tab", "actionFallback": "Moves focus to the card when it is interactive (link=true or href/to is set)."}, {"key": "Enter / Space", "actionKey": "components.card.a11y.key_activate", "actionFallback": "Activates the card link or click handler when focused."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-card---background", "descriptionKey": "components.card.tokens.background", "descriptionFallback": "Card background."}, {"type": "shadow", "value": "var(--origam-shadow---sm)", "tokenPath": "--origam-card---box-shadow", "descriptionKey": "components.card.tokens.box_shadow", "descriptionFallback": "Default elevation shadow."}, {"type": "shadow", "value": "var(--origam-shadow---lg)", "tokenPath": "--origam-card---box-shadow-hover", "descriptionKey": "components.card.tokens.box_shadow_hover", "descriptionFallback": "Hover elevation shadow for interactive cards."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-card---transition-duration", "descriptionKey": "components.card.tokens.transition_duration", "descriptionFallback": "Transition duration for shadow and opacity."}, {"type": "number", "value": "var(--origam-opacity---0)", "tokenPath": "--origam-card__overlay---opacity", "descriptionKey": "components.card.tokens.overlay_opacity", "descriptionFallback": "Resting overlay opacity (0 = invisible)."}, {"type": "number", "value": "var(--origam-opacity---12)", "tokenPath": "--origam-card---overlay-opacity-hover", "descriptionKey": "components.card.tokens.overlay_opacity_hover", "descriptionFallback": "Overlay opacity on hover (12%)."}, {"type": "number", "value": "var(--origam-opacity---60)", "tokenPath": "--origam-card---opacity-disabled", "descriptionKey": "components.card.tokens.opacity_disabled", "descriptionFallback": "Card opacity when disabled."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"320\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"280\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"5\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.3\"/>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"5\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" opacity=\"0\"/>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"68\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #525252)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-card-header: prepend / title / subtitle / append</text>\n  <rect x=\"50\" y=\"105\" width=\"600\" height=\"80\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"150\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__asset (image / #asset slot)</text>\n  <rect x=\"50\" y=\"190\" width=\"600\" height=\"80\" rx=\"0\" fill=\"var(--origam-color__surface---raised, #fff)\"/>\n  <text x=\"350\" y=\"235\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #525252)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__content: origam-card-text + #default slot</text>\n  <rect x=\"50\" y=\"275\" width=\"600\" height=\"25\" rx=\"0\" fill=\"var(--origam-color__surface---sunken, rgba(124,58,237,0.03))\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"350\" y=\"293\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__footer (#footer slot)</text>\n  <rect x=\"50\" y=\"20\" width=\"600\" height=\"280\" rx=\"8\" fill=\"var(--origam-color__overlay---scrim, rgba(0,0,0,0.04))\" stroke=\"none\" opacity=\"0\" class=\"origam-card__overlay\"/>\n  <circle cx=\"52\" cy=\"22\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"26\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"64\" cy=\"22\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"64\" y=\"26\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"52\" cy=\"107\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"111\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"52\" cy=\"192\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"52\" y=\"196\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"52\" cy=\"277\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"281\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "legend": [{"cls": ".origam-card", "num": 1, "descriptionKey": "components.card.anatomy.root", "descriptionFallback": "Root element. Defaults to <div>; becomes <a> when href/to is set. Carries color, shadow, rounded and density classes."}, {"cls": ".origam-card__overlay", "num": 2, "descriptionKey": "components.card.anatomy.overlay", "descriptionFallback": "Absolute scrim. opacity: 0 → overlay-opacity-hover on hover when the card is clickable. Driven by --origam-card__overlay---opacity."}, {"cls": ".origam-card__header", "num": 3, "descriptionKey": "components.card.anatomy.header", "descriptionFallback": "OrigamCardHeader. Rendered only when title, subtitle or prepend/append slots are populated."}, {"cls": ".origam-card__asset", "num": 4, "descriptionKey": "components.card.anatomy.asset", "descriptionFallback": "Image container rendered when the image prop or #asset slot is present. Contains <origam-img cover> by default."}, {"cls": ".origam-card__content", "num": 5, "descriptionKey": "components.card.anatomy.content", "descriptionFallback": "Main content wrapper. Contains OrigamCardText (if text prop is set) and the #default slot."}, {"cls": ".origam-card__text", "num": 6, "descriptionKey": "components.card.anatomy.text", "descriptionFallback": "OrigamCardText — density-aware padding wrapper around the text prop value."}, {"cls": ".origam-card__footer", "num": 7, "descriptionKey": "components.card.anatomy.footer", "descriptionFallback": "<div> rendered only when the #footer slot is populated. Typically contains action buttons."}, {"cls": ".origam-card__loader", "num": 8, "descriptionKey": "components.card.anatomy.loader", "descriptionFallback": "Loading overlay rendered when loading prop is set. Contains skeleton, progress-linear or progress-circular."}], "svgDesc": "Schematic of the Card component with 8 numbered internal parts.", "svgTitle": "Anatomy of OrigamCard", "rootClass": "origam-card", "figcaption": "Anatomy of <code>&lt;origam-card&gt;</code> — 5 visible parts: root ①, header ②, asset ③, content ④, footer ⑤. Two absolute layers (overlay for hover scrim and underlay) sit above the root.", "svgViewBox": "0 0 700 320"}, "cssVars": [{"name": "--origam-card---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.card.css_vars.background", "descriptionFallback": "Card surface background."}, {"name": "--origam-card---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.card.css_vars.color", "descriptionFallback": "Default text color."}, {"name": "--origam-card---box-shadow", "defaultValue": "{shadow.sm}", "descriptionKey": "components.card.css_vars.box_shadow", "descriptionFallback": "Default box-shadow. Overridden to shadow.lg on hover when link=true."}, {"name": "--origam-card---box-shadow-hover", "defaultValue": "{shadow.lg}", "descriptionKey": "components.card.css_vars.box_shadow_hover", "descriptionFallback": "Box-shadow on hover for interactive cards."}, {"name": "--origam-card---transition-duration", "defaultValue": "{motion.duration.slow}", "descriptionKey": "components.card.css_vars.transition_duration", "descriptionFallback": "Transition duration for shadow, opacity and background."}, {"name": "--origam-card---opacity", "defaultValue": "{opacity.100}", "descriptionKey": "components.card.css_vars.opacity", "descriptionFallback": "Card opacity. Set to opacity-disabled (0.6) when disabled."}, {"name": "--origam-card__overlay---opacity", "defaultValue": "0", "descriptionKey": "components.card.css_vars.overlay_opacity", "descriptionFallback": "Overlay scrim opacity. Animates to overlay-opacity-hover (0.12) on hover."}, {"name": "--origam-card---border-radius-rounded", "defaultValue": "{radius.md}", "descriptionKey": "components.card.css_vars.border_radius_rounded", "descriptionFallback": "Border-radius applied when rounded=true."}, {"name": "--origam-card---density", "defaultValue": "0px", "descriptionKey": "components.card.css_vars.density", "descriptionFallback": "Density offset applied to card padding."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.card.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<strin