INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4703932e-040d-4040-ad3c-ba16eefc9728', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'chart-honeycomb', 'ChartHoneycomb', 'Data Display', NULL, 'mdi-hexagon-multiple-outline', 'components.catalog.chart_honeycomb.description', 'Hexagonal tile-map chart. Renders a grid of SVG <polygon> hexagons positioned by (x=col, y=row) indices. Supports pointy-top and flat-top orientations, categorical and heatmap colour modes.', NULL, NULL, 'origam-chart-honeycomb', NULL, 'packages/ds/src/components/Chart/OrigamChartHoneycomb.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-honeycomb--design', '/docs/components/Chart/OrigamChartHoneycomb.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_honeycomb.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"honeycomb chart\")."}, {"noteKey": "components.chart_honeycomb.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing the tile count."}, {"noteKey": "components.chart_honeycomb.a11y.tile_aria", "noteFallback": "Each tile has aria-label derived from its name and value (e.g. \"A: 42\")."}, {"noteKey": "components.chart_honeycomb.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_honeycomb.a11y.key_tab", "actionFallback": "Moves focus through each hex tile (tabindex=\"0\") and legend items."}, {"key": "Enter / Space", "action