bel": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.next_icon", "defaultValue": "", "labelFallback": "Next Icon"}, {"kind": "select", "prop": "prevIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.prev_icon", "defaultValue": "", "labelFallback": "Prev Icon"}, {"kind": "select", "prop": "modeIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-account", "value": "mdi-account"}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-home", "value": "mdi-home"}, {"label": "mdi-close", "value": "mdi-close"}], "labelKey": "components.date_picker_controls.playground.mode_icon", "defaultValue": "", "labelFallback": "Mode Icon"}, {"kind": "switch", "prop": "disabledMonth", "labelKey": "components.date_picker_controls.playground.disabled_month", "defaultValue": false, "labelFallback": "Disabled Month"}, {"kind": "switch", "prop": "disabledYear", "labelKey": "components.date_picker_controls.playground.disabled_year", "defaultValue": false, "labelFallback": "Disabled Year"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('99932c4a-eb2c-4b21-ba09-148b804caccd', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'date-picker-field', 'DatePickerField', 'Form & Input', NULL, 'mdi-calendar-edit', 'components.catalog.date_picker_field.description', 'Text field with a built-in calendar dropdown. Combines OrigamTextField and OrigamDatePicker into a single form control with chip display for multiple/range selections.', NULL, NULL, 'origam-date-picker-field', NULL, 'packages/ds/src/components/DatePickerField/OrigamDatePickerField.vue', 'origam', NULL, NULL, '/stories/?story=components-datepickerfield--design', '/docs/components/DatePickerField/OrigamDatePickerField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.date_picker_field.a11y.aria_haspopup_note", "noteFallback": "The field sets aria-haspopup=\"datepickerbox\" on the inner input to signal that activating it opens a date picker. The calendar dropdown uses role=\"dialog\" with aria-modal=\"true\" when open."}, {"noteKey": "components.date_picker_field.a11y.label_note", "noteFallback": "The field must have a label (via the label prop or an external aria-label). Without a label, the calendar toggle icon is not accessible."}, {"noteKey": "components.date_picker_field.a11y.chip_note", "noteFallback": "In multiple/range mode, each chip has aria-label with the formatted date. Closable chips have an aria-label on the close button (\"Remove date X\")."}], "roles": ["combobox", "dialog"], "keyboard": [{"key": "Enter / Space (on field)", "actionKey": "components.date_picker_field.a11y.key_open", "actionFallback": "Opens the calendar dropdown."}, {"key": "Escape", "actionKey": "components.date_picker_field.a11y.key_close", "actionFallback": "Closes the calendar dropdown and returns focus to the field."}, {"key": "Tab", "actionKey": "components.date_picker_field.a11y.key_tab", "actionFallback": "Moves focus between the field, calendar navigation and days."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"240\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <rect x=\"60\" y=\"30\" width=\"580\" height=\"54\" rx=\"8\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(0,0,0,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"76\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"78\" y=\"54\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-date-picker-field</text>\n  <text x=\"80\" y=\"66\" font-size=\"12\" fill=\"var(--origam-color__text---disabled, #aaa)\" font-family=\"system-ui\">DD / MM / YYYY</text>\n  <circle cx=\"620\" cy=\"57\" r=\"14\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"none\"/>\n  <text x=\"620\" y=\"61\" font-size=\"16\" fill=\"var(--origam-color__text---secondary, #888)\" text-anchor=\"middle\">📅</text>\n  <circle cx=\"636\" cy=\"42\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"636\" y=\"46.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"60\" y=\"100\" width=\"580\" height=\"130\" rx=\"10\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, rgba(0,0,0,0.1))\" stroke-width=\"1.5\"/>\n  <circle cx=\"76\" cy=\"108\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"76\" y=\"112.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"145\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #888)\" text-anchor=\"middle\" font-family=\"system-ui\">OrigamDatePicker</text>\n  <text x=\"350\" y=\"168\" font-size=\"10\" fill=\"var(--origam-color__text---disabled, #bbb)\" text-anchor=\"middle\" font-family=\"system-ui\">(calendar grid)</text>\n  <text x=\"350\" y=\"220\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b0b0b0)\" text-anchor=\"middle\" font-style=\"italic\">① = text-field chrome. ② = appendInner calendar icon. ③ = DatePicker dropdown (OrigamMenu).</text>\n", "code": "<!-- DatePickerField = TextField chrome + Menu + DatePicker -->\n<origam-text-field class=\"origam-date-picker-field\" :aria-label=\"label\">\n\n  <!-- #prepend, #prependInner, #label, #prefix slots passthrough -->\n\n  <!-- selected dates as text or chips -->\n  <span class=\"origam-date-picker-field__selection-text\">\n    {{ formattedDates }}\n  </span>\n  <!-- OR chips in multiple/range mode -->\n  <origam-chip\n    v-for=\"date in selectedDates\"\n    :closable=\"closableChips\"\n    v-bind=\"chipProps\"\n  />\n\n  <!-- #suffix, #clear slots passthrough -->\n\n  <!-- calendar toggle icon -->\n  <template #appendInner>\n    <origam-icon icon=\"mdi-calendar\" />\n  </template>\n\n  <!-- #append slot passthrough -->\n\n  <!-- floating DatePicker -->\n  <origam-menu\n    v-model=\"menu\"\n    content-class=\"origam-date-picker-field__content\"\n  >\n    <origam-date-picker v-model=\"model\" />\n  </origam-menu>\n</origam-text-field>", "legend": [{"cls": ".origam-date-picker-field (TextField root)", "num": 1, "descriptionKey": "components.date_picker_field.anatomy.field", "descriptionFallback": "TextField chrome — label, border, density, variant. The selected date(s) appear as formatted text or chips inside the control area. Extends all ITextFieldProps."}, {"cls": "appendInner — calendar toggle icon", "num": 2, "descriptionKey": "components.date_picker_field.anatomy.toggle_icon", "descriptionFallback": "Calendar icon rendered in the appendInner slot by default (mdi-calendar). Clicking it toggles the menu open/closed. aria-label comes from openText/closeText props."}, {"cls": "OrigamMenu + OrigamDatePicker", "num": 3, "descriptionKey": "components.date_picker_field.anatomy.menu", "descriptionFallback": "Floating menu (OrigamMenu) containing the full OrigamDatePicker. Positioned below the field with an offset from --origam-date-picker-field---menu-offset. Content class: origam-date-picker-field__content."}], "classes": [{"cls": "origam-date-picker-field", "descriptionKey": "components.date_picker_field.anatomy.root", "descriptionFallback": "Root — extends TextField BEM classes."}, {"cls": "origam-date-picker-field__selection-text", "descriptionKey": "components.date_picker_field.anatomy.selection_text", "descriptionFallback": "Formatted date text displayed in the field when mode is single."}, {"cls": "origam-date-picker-field__selection-chips", "descriptionKey": "components.date_picker_field.anatomy.selection_chips", "descriptionFallback": "Chip container in multiple/range mode."}, {"cls": "origam-date-picker-field__content", "descriptionKey": "components.date_picker_field.anatomy.content", "descriptionFallback": "Menu content class applied to the OrigamMenu teleport target."}], "svgDesc": "Schematic of the DatePickerField component with numbered internal parts.", "svgTitle": "Anatomy of OrigamDatePickerField", "rootClass": "origam-date-picker-field", "figcaption": "Anatomy of <code>&lt;origam-date-picker-field&gt;</code>. The component combines an <code>OrigamTextField</code> chrome ① with a calendar toggle icon ② that opens an <code>OrigamMenu</code> containing <code>OrigamDatePicker</code> ③.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-date-picker-field---min-width", "defaultValue": "200px", "descriptionKey": "components.date_picker_field.css_vars.min_width", "descriptionFallback": "Minimum field width."}, {"name": "--origam-date-picker-field---max-width", "defaultValue": "320px", "descriptionKey": "components.date_picker_field.css_vars.max_width", "descriptionFallback": "Maximum field width."}, {"name": "--origam-date-picker-field---menu-offset", "defaultValue": "{space.1}", "descriptionKey": "components.date_picker_field.css_vars.menu_offset", "descriptionFallback": "Vertical gap between the field bottom and the calendar dropdown."}, {"name": "--origam-date-picker-field__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.date_picker_field.css_vars.icon_color", "descriptionFallback": "Default colour of the calendar toggle icon."}, {"name": "--origam-date-picker-field__icon---color-hover", "defaultValue": "{color.text.primary}", "descriptionKey": "components.date_picker_field.css_vars.icon_color_hover", "descriptionFallback": "Icon colour on hover."}, {"name": "--origam-date-picker-field__icon---color-error", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.date_picker_field.css_vars.icon_color_error", "descriptionFallback": "Icon colour in error state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_field.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "isFocused", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.is_focused", "descriptionFallback": "Whether the field is currently focused."}, {"name": "menu", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.menu", "descriptionFallback": "Whether the calendar dropdown is currently open."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_field.exposed.css", "descriptionFallback": "Reactive CSS string for the injected style sheet."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_field.exposed.load", "descriptionFallback": "Injects the style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_field.exposed.unload", "descriptionFallback": "Removes the style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}, {"label": "solo-filled", "value": "solo-filled"}], "labelKey": "components.date_picker_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "color", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.date_picker_field.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}, {"label": "compact", "value": "compact"}], "labelKey": "components.date_picker_field.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "range", "labelKey": "components.date_picker_field.playground.range", "defaultValue": false, "labelFallback": "Range mode"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.date_picker_field.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "clearable", "labelKey": "components.date_picker_field.playground.clearable", "defaultValue": false, "labelFallback": "Clearable"}, {"kind": "switch", "prop": "closableChips", "labelKey": "components.date_picker_field.playground.closable_chips", "defaultValue": false, "labelFallback": "Closable chips"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.date_picker_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "single", "props": {"color": "primary", "label": "Date", "variant": "outlined"}}, {"label": "range", "props": {"color": "primary", "label": "Date range", "range": true, "variant": "outlined"}}, {"label": "multiple", "props": {"color": "primary", "label": "Multiple dates", "variant": "outlined", "multiple": true, "closableChips": true}}, {"label": "clearable", "props": {"color": "primary", "label": "Date", "variant": "outlined", "clearable": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('972542d4-2a3a-4a2a-aca7-b12e3f007690', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'date-picker-header', 'DatePickerHeader', 'Form & Input', NULL, 'mdi-calendar-today', 'components.catalog.date_picker_header.description', 'Header banner of the DatePicker displaying the currently selected date value with animated transitions. Supports prepend/append slots and emits a click event for interactive headers.', NULL, NULL, 'origam-date-picker-header', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerHeader.vue', 'origam', NULL, NULL, NULL, NULL, 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_header.a11y.transition", "noteFallback": "OrigamTransition wraps the content; reduced-motion is respected by the transition component."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_header.a11y.key_activate", "actionFallback": "Activates the header click when it is keyboard-focusable."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "32px", "tokenPath": "--origam-date-picker__header---font-size", "descriptionKey": "components.date_picker_header.tokens.font_size", "descriptionFallback": "Header font size."}, {"type": "dimension", "value": "70px", "tokenPath": "--origam-date-picker__header---min-height", "descriptionKey": "components.date_picker_header.tokens.min_height", "descriptionFallback": "Header minimum height."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"100\" rx=\"4\" fill=\"