INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('edab9ae7-a326-4602-9a96-75e83607276a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'expansion-panel-header', 'ExpansionPanelHeader', 'Layout & Structure', NULL, 'mdi-chevron-down-box', 'components.catalog.expansion_panel_header.description', 'Clickable header button with expand/collapse icon, prepend/append slots and ripple support. Carries aria-expanded and aria-controls.', NULL, NULL, 'origam-expansion-panel-header', NULL, 'packages/ds/src/components/ExpansionPanel/OrigamExpansionPanelHeader.vue', 'origam', NULL, NULL, '/stories/?story=components-expansionpanel--design', '/docs/components/ExpansionPanel/OrigamExpansionPanel.html', 'expansion-panel', '{"a11y": {"notes": [{"noteKey": "components.expansion_panel_header.a11y.aria_expanded", "noteFallback": "The header button carries aria-expanded=\"true|false\" reflecting the current panel selection state."}, {"noteKey": "components.expansion_panel_header.a11y.aria_controls", "noteFallback": "The header button carries aria-controls pointing to the content region ID (expansion-panel-content-{id})."}, {"noteKey": "components.expansion_panel_header.a11y.disabled", "noteFallback": "Disabled panels apply tabindex=\"-1\" and the disabled HTML attribute to the header button. Pointer events are removed."}, {"noteKey": "components.expansion_panel_header.a11y.readonly", "noteFallback": "When readonly is true, clicks are intercepted but not propagated — the button remains focusable and receives keyboard events without toggling."}, {"noteKey": "components.expansion_panel_header.a11y.ripple", "noteFallback