ill."}, {"name": "--origam-sheet__handle---height", "defaultValue": "4px", "descriptionKey": "components.sheet.css_vars.handle_height", "descriptionFallback": "Height of the drag handle pill."}, {"name": "--origam-sheet__handle---color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.sheet.css_vars.handle_color", "descriptionFallback": "Background color of the drag handle pill."}, {"name": "--origam-sheet__swipeable---border-radius", "defaultValue": "{radius.2xl}", "descriptionKey": "components.sheet.css_vars.swipeable_border_radius", "descriptionFallback": "Border-radius applied to top corners when swipeable=true."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.sheet.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "snapTo", "type": "(id: TSheetSnapId) => void", "descriptionKey": "components.sheet.exposed.snap_to", "descriptionFallback": "Imperatively snap the sheet to a given snap-point id."}, {"name": "currentSnap", "type": "Ref<TSheetSnapId>", "descriptionKey": "components.sheet.exposed.current_snap", "descriptionFallback": "Reactive current snap-point id."}, {"name": "isDragging", "type": "Ref<boolean>", "descriptionKey": "components.sheet.exposed.is_dragging", "descriptionFallback": "True while the user is dragging the sheet handle."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.sheet.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.sheet.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.sheet.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descript