INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d2dae242-ba8f-4f00-9f8f-02111247f274', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'text-mask', 'TextMask', 'Data Display', NULL, 'mdi-format-color-text', 'components.catalog.text_mask.description', 'Renders text with a gradient or image as a transparent fill via background-clip: text. Supports animated gradients (pan, rotate, pulse, zoom).', NULL, NULL, 'origam-text-mask', NULL, 'packages/ds/src/components/TextMask/OrigamTextMask.vue', 'origam', NULL, NULL, '/stories/?story=components-textmask--design', '/docs/components/TextMask/OrigamTextMask.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.text_mask.a11y.dom_text_note", "noteFallback": "The text content is preserved in the DOM as plain text (or semantic slot content). The background-clip:text transform is purely CSS — screen readers and search engines read the real text."}, {"noteKey": "components.text_mask.a11y.reduced_motion_note", "noteFallback": "All CSS animations are disabled under prefers-reduced-motion: reduce. The background-size reverts to cover so the gradient is still visible."}, {"noteKey": "components.text_mask.a11y.contrast_note", "noteFallback": "Gradient backgrounds may produce low-contrast regions. Verify WCAG AA contrast ratios for the minimum-contrast point of the gradient. Add a fallback color for browsers that do not support background-clip:text."}], "roles": ["(none — inline text)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-font__size---5xl)", "tokenPath": "--origam-text-mask---font-size-default", "descriptionKey": "components.text_mask.tokens.font_size_default", "descriptionFallback": "Reference display font size used in the DS story defaults."}, {"type": "fontWeight", "value": "var(--origam-font__weight---bold)", "tokenPath": "--origam-text-mask---font-weight-default", "descriptionKey": "components.text_mask.tokens.font_weight_default", "descriptionFallback": "Reference font weight used in the DS story defaults."}, {"type": "number", "value": "var(--origam-font__lineHeight---tight)", "tokenPath": "--origam-text-mask---line-height-default", "descriptionKey": "components.text_mask.tokens.line_height_default", "descriptionFallback": "Tight line-height suited to large display text."}, {"type": "duration", "value": "3s", "tokenPath": "--origam-text-mask__animation---duration-default", "descriptionKey": "components.text_mask.tokens.animation_duration", "descriptionFallback": "Default animation cycle duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <defs>\n    <linearGradient id=\"tmGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n      <stop offset=\"0%\" style=\"stop-color:#7c3aed\"/>\n      <stop offset=\"50%\" style=\"stop-color:#a855f7\"/>\n      <stop offset=\"100%\" style=\"stop-color:#06b6d4\"/>\n    </linearGradient>\n  </defs>\n  <text x=\"300\" y=\"92\" font-size=\"32\" fill=\"url(#tmGrad)\" font-weight=\"900\" text-anchor=\"middle\" font-family=\"sans-serif\">Hello World</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-text-mask</text>\n  <text x=\"300\" y=\"148\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">background-clip: text · -webkit-text-fill-color: transparent</text>\n", "code": "<!-- root: inline-block with background-clip: text -->\n<component\n  :is=\"tag\"\n  class=\"origam-text-mask\"\n  :class=\"[\n    `origam-text-mask--align-${align}`,\n    `origam-text-mask--${animationType}`,\n    { ''origam-text-mask--animated'': animated }\n  ]\"\n  :style=\"{\n    ''--origam-text-mask---bg'': resolvedBackground,\n    ''--origam-text-mask---font-size'': ...,\n    ''--origam-text-mask---font-weight'': ...,\n  }\"\n>\n  <!-- slot content (wins over text prop) -->\n  <slot v-if=\"hasSlot\"/>\n  <template v-else>{{ text }}</template>\n</component>", "legend": [{"cls": ".origam-text-mask", "num": 1, "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element (span by default). Sets background-image, background-clip:text and -webkit-text-fill-color:transparent. Animation classes are added when animated=true."}], "classes": [{"cls": "origam-text-mask", "descriptionKey": "components.text_mask.anatomy.root", "descriptionFallback": "Root element. display:inline-block with background-clip:text."}, {"cls": "origam-text-mask--align-left", "descriptionKey": "components.text_mask.anatomy.align_left", "descriptionFallback": "text-align: left (default)."}, {"cls": "origam-text-mask--align-center", "descriptionKey": "components.text_mask.anatomy.align_center", "descriptionFallback": "text-align: center."}, {"cls": "origam-text-mask--align-right", "descriptionKey": "components.text_mask.anatomy.align_right", "descriptionFallback": "text-align: right."}, {"cls": "origam-text-mask--animated", "descriptionKey": "components.text_mask.anatomy.animated", "descriptionFallback": "Added when animated=true. Enables the keyframe animation selected by --{animationType}."}, {"cls": "origam-text-mask--pan", "descriptionKey": "components.text_mask.anatomy.pan", "descriptionFallback": "Horizontal pan animation (background-position 0% → 100%)."}, {"cls": "origam-text-mask--rotate", "descriptionKey": "components.text_mask.anatomy.rotate", "descriptionFallback": "Hue-rotate animation (filter: hue-rotate 0 → 360deg)."}, {"cls": "origam-text-mask--pulse", "descriptionKey": "components.text_mask.anatomy.pulse", "descriptionFallback": "Size pulse animation (background-size oscillates)."}, {"cls": "origam-text-mask--zoom", "descriptionKey": "components.text_mask.anatomy.zoom", "descriptionFallback": "Zoom animation (background-size 100% → 220%)."}], "svgDesc": "Schematic of the TextMask component — root with inline background-clip style.", "svgTitle": "Anatomy of OrigamTextMask", "rootClass": "origam-text-mask", "figcaption": "Anatomy of <code>&lt;origam-text-mask&gt;</code> — single root element with <code>background-clip: text</code>. The text content is preserved in the DOM; the gradient/image visual is CSS-only.", "svgViewBox": "0 0 600 160"}, "cssVars": [{"name": "--origam-text-mask---bg", "defaultValue": "undefined", "descriptionKey": "components.text_mask.css_vars.bg", "descriptionFallback": "Resolved background-image value (gradient or url()). Set from the background prop."}, {"name": "--origam-text-mask---duration", "defaultValue": "3s", "descriptionKey": "components.text_mask.css_vars.duration", "descriptionFallback": "Animation cycle duration. Maps to animationDuration prop."}, {"name": "--origam-text-mask---font-size", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_size", "descriptionFallback": "Font size of the masked text."}, {"name": "--origam-text-mask---font-weight", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_weight", "descriptionFallback": "Font weight of the masked text."}, {"name": "--origam-text-mask---font-family", "defaultValue": "inherit", "descriptionKey": "components.text_mask.css_vars.font_family", "descriptionFallback": "Font family of the masked text."}, {"name": "--origam-text-mask---line-height", "defaultValue": "1.1", "descriptionKey": "components.text_mask.css_vars.line_height", "descriptionFallback": "Line height of the masked text."}, {"name": "--origam-text-mask---letter-spacing", "defaultValue": "normal", "descriptionKey": "components.text_mask.css_vars.letter_spacing", "descriptionFallback": "Letter spacing of the masked text."}], "exposed": [{"name": "resolvedBackground", "type": "ComputedRef<string>", "descriptionKey": "components.text_mask.exposed.resolved_background", "descriptionFallback": "The resolved background-image CSS value (gradient or url()). Derived from the background prop after resolveGradient() processing."}, {"name": "hasSlot", "type": "ComputedRef<boolean>", "descriptionKey": "components.text_mask.exposed.has_slot", "descriptionFallback": "True when the default slot is provided. When false, the text prop is rendered."}], "playground": {"controls": [{"kind": "select", "prop": "background", "options": [{"label": "Violet → Cyan", "value": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)"}, {"label": "Sunset", "value": "linear-gradient(135deg, #f59e0b, #ef4444, #a855f7)"}, {"label": "Ocean", "value": "linear-gradient(135deg, #06b6d4, #3b82f6, #6366f1)"}, {"label": "Forest", "value": "linear-gradient(135deg, #10b981, #059669, #3b82f6)"}], "labelKey": "components.text_mask.playground.background", "defaultValue": "linear-gradient(90deg, #7c3aed, #a855f7, #06b6d4)", "labelFallback": "Background"}, {"kind": "switch", "prop": "animated", "labelKey": "components.text_mask.playground.animated", "defaultValue": false, "labelFallback": "Animated"}, {"kind": "select", "prop": "animationType", "options": [{"label": "pan", "value": "pan"}, {"label": "rotate", "value": "rotate"}, {"label": "pulse", "value": "pulse"}, {"label": "zoom", "value": "zoom"}], "labelKey": "components.text_mask.playground.animation_type", "defaultValue": "pan", "labelFallback": "Animation type"}, {"kind": "number", "prop": "fontSize", "labelKey": "components.text_mask.playground.font_size", "defaultValue": 48, "labelFallback": "Font size (px)"}, {"kind": "select", "prop": "fontWeight", "options": [{"label": "400", "value": 400}, {"label": "600", "value": 600}, {"label": "700", "value": 700}, {"label": "800", "value": 800}, {"label": "900", "value": 900}], "labelKey": "components.text_mask.playground.font_weight", "defaultValue": 800, "labelFallback": "Font weight"}, {"kind": "select", "prop": "align", "options": [{"label": "left", "value": "left"}, {"label": "center", "value": "center"}, {"label": "right", "value": "right"}], "labelKey": "components.text_mask.playground.align", "defaultValue": "left", "labelFallback": "Align"}], "defaultSlotContent": "Origam DS"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4982996b-d02d-436c-a611-61f93bfbeee1', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'theme-provider', 'ThemeProvider', 'Utilities & Providers', NULL, 'mdi-palette-swatch-outline', 'components.catalog.theme_provider.description', 'Overrides the active theme and/or color mode for a sub-tree by setting data-theme and data-mode attributes on a display:contents wrapper.', NULL, NULL, 'origam-theme-provider', NULL, 'packages/ds/src/components/ThemeProvider/OrigamThemeProvider.vue', 'origam', NULL, NULL, '/stories/?story=components-themeprovider--design', '/docs/components/ThemeProvider/OrigamThemeProvider.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.theme_provider.a11y.contents_note", "noteFallback": "The root wrapper uses display:contents — it is invisible to the layout engine and does not create an extra stacking context or box. It should not affect the accessibility tree of its children."}, {"noteKey": "components.theme_provider.a11y.tag_note", "noteFallback": "When the sub-tree is a semantic region, use tag=''section'' or tag=''article'' to add semantic meaning to the wrapper instead of the invisible div default."}], "roles": ["(none — display:contents wrapper)"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"544\" height=\"160\" rx=\"4\" fill=\"transparent\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"8 4\"/>\n  <text x=\"300\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">data-theme=\"ocean\" data-mode=\"dark\"</text>\n  <text x=\"300\" y=\"62\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">display: contents — no layout impact</text>\n  <rect x=\"80\" y=\"80\" width=\"200\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"180\" y=\"126\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">child component A</text>\n  <rect x=\"320\" y=\"80\" width=\"200\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"420\" y=\"126\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">child component B</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-theme-provider</text>\n", "code": "<!-- root: display:contents — no layout impact -->\n<component\n  :is=\"tag\"\n  class=\"origam-theme-provider\"\n  :data-theme=\"theme !== ''auto'' ? theme : undefined\"\n  :data-mode=\"mode !== ''auto'' ? mode : undefined\"\n>\n  <!-- all children resolve CSS vars from this scope -->\n  <slot />\n</component>", "legend": [{"cls": ".origam-theme-provider", "num": 1, "descriptionKey": "components.theme_provider.anatomy.root", "descriptionFallback": "Root wrapper element (div by default). display:contents ensures it has no layout impact. data-theme and data-mode are set from the theme and mode props, enabling CSS variable scope resolution for all descendant components."}], "classes": [{"cls": "origam-theme-provider", "descriptionKey": "components.theme_provider.anatomy.root", "descriptionFallback": "Root wrapper. display:contents. Sole purpose is to carry data-theme / data-mode attribute for CSS scope."}], "svgDesc": "Schematic of the ThemeProvider — a display:contents wrapper that rewrites data-theme / data-mode.", "svgTitle": "Anatomy of OrigamThemeProvider", "rootClass": "origam-theme-provider", "figcaption": "Anatomy of <code>&lt;origam-theme-provider&gt;</code> — a single <code>display:contents</code> wrapper ① that rewrites <code>data-theme</code> and <code>data-mode</code> on its root element. Child components resolve their CSS custom properties against this new scope automatically.", "svgViewBox": "0 0 600 200"}, "playground": {"controls": [{"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "MODE.HORIZONTAL", "value": "MODE.HORIZONTAL"}, {"label": "horizontal", "value": "horizontal"}, {"label": "MODE.VERTICAL", "value": "MODE.VERTICAL"}, {"label": "vertical", "value": "vertical"}, {"label": "shift", "value": "shift"}, {"label": "MODE.SHIFT", "value": "MODE.SHIFT"}], "labelKey": "components.theme_provider.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1becdd8e-ba25-4a7b-bd42-43b1e6aa62a8', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'timeline', 'Timeline', 'Data Display', NULL, 'mdi-timeline-outline', 'components.catalog.timeline.description', 'Vertical or horizontal event timeline with dot, connector and item content slots. Supports alternating layout, custom intents per item, and scroll-snapping in horizontal mode.', NULL, NULL, 'origam-timeline', NULL, 'packages/ds/src/components/Timeline/OrigamTimeline.vue', 'origam', NULL, NULL, '/stories/?story=components-timeline--design', '/docs/components/Timeline/OrigamTimeline.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.timeline.a11y.list_note", "noteFallback": "The root element has role=\"list\". Each OrigamTimelineItem has role=\"listitem\". Screen readers announce the number of items in the timeline."}, {"noteKey": "components.timeline.a11y.label_note", "noteFallback": "Provide an ariaLabel prop to describe the timeline purpose (e.g. \"Project history\"). Without it, screen readers will not contextualise the list."}, {"noteKey": "components.timeline.a11y.connector_note", "noteFallback": "The track column (dot + connector) has aria-hidden=\"true\" — it is decorative. Meaningful content lives in the content area."}], "roles": ["list", "listitem (per item)"], "keyboard": [{"key": "Tab", "actionKey": "components.timeline.a11y.key_tab", "actionFallback": "Moves focus between interactive elements inside the timeline items (links, buttons in content slots)."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-timeline---gap", "descriptionKey": "components.timeline.tokens.gap", "descriptionFallback": "Gap between items."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-timeline---dot-size", "descriptionKey": "components.timeline.tokens.dot_size", "descriptionFallback": "Dot diameter."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-timeline---dot-bg", "descriptionKey": "components.timeline.tokens.dot_bg", "descriptionFallback": "Default dot background color."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-timeline---connector-color", "descriptionKey": "components.timeline.tokens.connector_color", "descriptionFallback": "Connector line color."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-timeline---connector-thickness", "descriptionKey": "components.timeline.tokens.connector_thickness", "descriptionFallback": "Connector line width."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-timeline---title-font-weight", "descriptionKey": "components.timeline.tokens.title_font_weight", "descriptionFallback": "Title font weight."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"20\" width=\"544\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"70\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"80\" x2=\"120\" y2=\"150\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"160\" r=\"10\" fill=\"var(--origam-color__feedback--success---bg, #10b981)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"170\" x2=\"120\" y2=\"240\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <circle cx=\"120\" cy=\"250\" r=\"10\" fill=\"var(--origam-color__feedback--info---bg, #06b6d4)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <rect x=\"148\" y=\"50\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"76\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Account created</text>\n  <rect x=\"148\" y=\"140\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"166\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Profile completed</text>\n  <rect x=\"148\" y=\"230\" width=\"380\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"160\" y=\"256\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">First payment</text>\n  <circle cx=\"36\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"32.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"110\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"132\" cy=\"82\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"132\" y=\"86.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"148\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"62.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <line x1=\"46\" y1=\"20\" x2=\"80\" y2=\"6\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-timeline</text>\n", "code": "<!-- root: role=\"list\" -->\n<component :is=\"tag\" class=\"origam-timeline\" role=\"list\" :aria-label=\"ariaLabel\">\n  <!-- horizontal mode wraps items in a scroll-snap track -->\n  <div v-if=\"orientation === ''horizontal''\" class=\"origam-timeline__track-wrapper\">\n    <slot>\n      <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n    </slot>\n  </div>\n\n  <!-- vertical mode: direct slot -->\n  <slot v-else>\n    <origam-timeline-item v-for=\"(entry, i) in items\" :key=\"i\" v-bind=\"entry\" />\n  </slot>\n</component>", "legend": [{"cls": ".origam-timeline", "num": 1, "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element with role=\"list\". Contains a track-wrapper div in horizontal mode."}, {"cls": ".origam-timeline-item__dot", "num": 2, "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Background color driven by the item intent via --origam-timeline-item---dot-bg. Hosts the #dot slot (icon by default when icon prop is set)."}, {"cls": ".origam-timeline-item__connector", "num": 3, "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Vertical (or horizontal) line connecting consecutive dots. Hidden on the last item when truncateLine=true."}, {"cls": ".origam-timeline-item__content", "num": 4, "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area next to the dot. Contains the header (title + subtitle) and an optional body. Hosts the #default and #body slots."}], "classes": [{"cls": "origam-timeline", "descriptionKey": "components.timeline.anatomy.root", "descriptionFallback": "Root element (role=\"list\")."}, {"cls": "origam-timeline__track-wrapper", "descriptionKey": "components.timeline.anatomy.track_wrapper", "descriptionFallback": "Horizontal scroll container. Only rendered when orientation=\"horizontal\"."}, {"cls": "origam-timeline-item", "descriptionKey": "components.timeline.anatomy.item", "descriptionFallback": "Individual timeline entry (role=\"listitem\")."}, {"cls": "origam-timeline-item__track", "descriptionKey": "components.timeline.anatomy.track", "descriptionFallback": "Track column: dot + connector (aria-hidden)."}, {"cls": "origam-timeline-item__dot", "descriptionKey": "components.timeline.anatomy.dot", "descriptionFallback": "Circular dot. Intent-colored background."}, {"cls": "origam-timeline-item__connector", "descriptionKey": "components.timeline.anatomy.connector", "descriptionFallback": "Line connecting this dot to the next."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline.anatomy.content", "descriptionFallback": "Content area: header + body."}], "svgDesc": "Schematic of the Timeline component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimeline", "rootClass": "origam-timeline", "figcaption": "Anatomy of <code>&lt;origam-timeline&gt;</code> — 4 internal parts: root list ①, dot ②, connector ③ and content area ④ per item.", "svgViewBox": "0 0 600 300"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "{space.4}", "descriptionKey": "components.timeline.css_vars.gap", "descriptionFallback": "Gap between timeline items and between the dot and content."}, {"name": "--origam-timeline---dot-size", "defaultValue": "{space.3}", "descriptionKey": "components.timeline.css_vars.dot_size", "descriptionFallback": "Diameter of the dot."}, {"name": "--origam-timeline---dot-bg", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.timeline.css_vars.dot_bg", "descriptionFallback": "Default dot background color (overridden per item by intent)."}, {"name": "--origam-timeline---dot-color", "defaultValue": "{color.action.primary.fg}", "descriptionKey": "components.timeline.css_vars.dot_color", "descriptionFallback": "Default dot foreground (icon) color."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "{border.width.thin}", "descriptionKey": "components.timeline.css_vars.connector_thickness", "descriptionFallback": "Width/height of the connector line."}, {"name": "--origam-timeline---track-width", "defaultValue": "{space.6}", "descriptionKey": "components.timeline.css_vars.track_width", "descriptionFallback": "Width of the track column (dot + connector area)."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "{font.size.md}", "descriptionKey": "components.timeline.css_vars.title_font_size", "descriptionFallback": "Font size of the item title."}, {"name": "--origam-timeline---subtitle-color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.timeline.css_vars.subtitle_color", "descriptionFallback": "Color of the item subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.timeline.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.timeline.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.timeline.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.timeline.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.timeline.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "orientation", "options": [{"label": "vertical", "value": "vertical"}, {"label": "horizontal", "value": "horizontal"}], "labelKey": "components.timeline.playground.orientation", "defaultValue": "vertical", "labelFallback": "Orientation"}, {"kind": "select", "prop": "side", "options": [{"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "alternating", "value": "alternating"}], "labelKey": "components.timeline.playground.side", "defaultValue": "start", "labelFallback": "Side"}, {"kind": "switch", "prop": "truncateLine", "labelKey": "components.timeline.playground.truncate_line", "defaultValue": true, "labelFallback": "Truncate last connector"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "info", "value": "info"}], "labelKey": "components.timeline.playground.color", "defaultValue": "primary", "labelFallback": "Default color"}]}, "previewVariants": [{"label": "vertical 3 items", "props": {"side": "start", "orientation": "vertical", "truncateLine": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('48f5a808-4f83-4a6f-ba7a-084b0fb020cd', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'timeline-item', 'TimelineItem', 'Data Display', NULL, 'mdi-timeline-outline', 'components.catalog.timeline_item.description', 'Individual event entry inside an OrigamTimeline — renders a dot, connector and content area with optional title, subtitle, body, icon and intent.', NULL, NULL, 'origam-timeline-item', NULL, 'packages/ds/src/components/Timeline/OrigamTimelineItem.vue', 'origam', NULL, NULL, '/stories/?story=components-timeline--design', '/docs/components/Timeline/OrigamTimeline.html', 'timeline', '{"a11y": {"notes": [{"noteKey": "components.timeline_item.a11y.role_note", "noteFallback": "OrigamTimelineItem uses role=\"listitem\" matching the parent OrigamTimeline role=\"list\". The track area (dot + connector) is aria-hidden=\"true\" — it is decorative."}, {"noteKey": "components.timeline_item.a11y.icon_note", "noteFallback": "Icons inside the dot are decorative and aria-hidden by the parent track. If the icon conveys status, provide the information via title or description for screen readers."}], "roles": ["listitem"], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-timeline---dot-size", "descriptionKey": "components.timeline_item.tokens.dot_size", "descriptionFallback": "Diameter of the timeline dot."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-timeline---dot-bg", "descriptionKey": "components.timeline_item.tokens.dot_bg", "descriptionFallback": "Default dot background color (overridden per-item by intent)."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-timeline---connector-color", "descriptionKey": "components.timeline_item.tokens.connector_color", "descriptionFallback": "Connector line color."}, {"type": "dimension", "value": "var(--origam-border__width---thin)", "tokenPath": "--origam-timeline---connector-thickness", "descriptionKey": "components.timeline_item.tokens.connector_thickness", "descriptionFallback": "Connector line thickness."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-timeline---title-font-weight", "descriptionKey": "components.timeline_item.tokens.title_font_weight", "descriptionFallback": "Font weight of the item title."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-timeline---subtitle-color", "descriptionKey": "components.timeline_item.tokens.subtitle_color", "descriptionFallback": "Color of subtitle and body text."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"640\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <!-- root -->\n  <rect x=\"20\" y=\"30\" width=\"600\" height=\"200\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- track -->\n  <rect x=\"40\" y=\"50\" width=\"40\" height=\"160\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\"/>\n  <!-- dot -->\n  <circle cx=\"60\" cy=\"80\" r=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke=\"var(--origam-color__surface---default, #fff)\" stroke-width=\"2\"/>\n  <text x=\"60\" y=\"85\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <!-- connector -->\n  <line x1=\"60\" y1=\"96\" x2=\"60\" y2=\"200\" stroke=\"var(--origam-color__border---subtle, rgba(168,85,247,0.3))\" stroke-width=\"2\" stroke-dasharray=\"4 2\"/>\n  <!-- content -->\n  <rect x=\"100\" y=\"50\" width=\"500\" height=\"160\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\"/>\n  <!-- header -->\n  <rect x=\"116\" y=\"66\" width=\"460\" height=\"44\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"200\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #1a1035)\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"600\">title</text>\n  <text x=\"200\" y=\"100\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">subtitle</text>\n  <!-- body -->\n  <rect x=\"116\" y=\"120\" width=\"460\" height=\"72\" rx=\"2\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"346\" y=\"160\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">body / description</text>\n  <!-- number circles -->\n  <circle cx=\"30\" cy=\"38\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"30\" y=\"42.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"48\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"60\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" stroke=\"none\"/>\n  <text x=\"60\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"60\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"60\" y=\"152\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"110\" cy=\"58\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"110\" y=\"62\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"120\" cy=\"74\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"78\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <circle cx=\"120\" cy=\"128\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"120\" y=\"132\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">7</text>\n  <line x1=\"30\" y1=\"26\" x2=\"58\" y2=\"10\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"62\" y=\"8\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-timeline-item</text>\n  <text x=\"320\" y=\"248\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">③ dot · ④ connector · ⑥ header · ⑦ body — inside track ② and content ⑤</text>\n", "code": "<!-- root: role=\"listitem\" -->\n<div class=\"origam-timeline-item origam-timeline-item--orientation-vertical\">\n  <!-- track: dot + connector -->\n  <div class=\"origam-timeline-item__track\" aria-hidden=\"true\">\n    <div class=\"origam-timeline-item__dot\">\n      <slot name=\"dot\">\n        <origam-icon v-if=\"icon\" :icon=\"icon\" :size=\"10\" />\n      </slot>\n    </div>\n    <span v-if=\"showConnector\" class=\"origam-timeline-item__connector\" />\n  </div>\n\n  <!-- content area -->\n  <div class=\"origam-timeline-item__content\">\n    <slot name=\"default\">\n      <div class=\"origam-timeline-item__header\">\n        <span class=\"origam-timeline-item__title\">{{ title }}</span>\n        <span class=\"origam-timeline-item__subtitle\">{{ subtitle }}</span>\n      </div>\n      <div class=\"origam-timeline-item__body\">\n        <slot name=\"body\">{{ description }}</slot>\n      </div>\n    </slot>\n  </div>\n</div>", "legend": [{"cls": ".origam-timeline-item", "num": 1, "descriptionKey": "components.timeline_item.anatomy.root", "descriptionFallback": "Root element. <code>role=\"listitem\"</code>, flex row. Orientation modifier class switches to flex-column in horizontal mode."}, {"cls": ".origam-timeline-item__track", "num": 2, "descriptionKey": "components.timeline_item.anatomy.track", "descriptionFallback": "Track column: contains the dot and connector, flex-column, fixed width. In horizontal mode switches to flex-row."}, {"cls": ".origam-timeline-item__dot", "num": 3, "descriptionKey": "components.timeline_item.anatomy.dot", "descriptionFallback": "Colored dot circle. Background and foreground color driven by the resolved intent via CSS custom properties."}, {"cls": ".origam-timeline-item__connector", "num": 4, "descriptionKey": "components.timeline_item.anatomy.connector", "descriptionFallback": "Connector line between dots. Hidden when <code>isLast=true</code> and <code>truncateLine=true</code>."}, {"cls": ".origam-timeline-item__content", "num": 5, "descriptionKey": "components.timeline_item.anatomy.content", "descriptionFallback": "Content area, flex: 1. Hosts the header and body sub-elements or the entire default slot."}, {"cls": ".origam-timeline-item__header", "num": 6, "descriptionKey": "components.timeline_item.anatomy.header", "descriptionFallback": "Header row containing title and subtitle spans. Visible only when default slot is not used."}, {"cls": ".origam-timeline-item__body", "num": 7, "descriptionKey": "components.timeline_item.anatomy.body", "descriptionFallback": "Body text area. Rendered when description prop or the body slot is provided."}], "classes": [{"cls": "origam-timeline-item", "descriptionKey": "components.timeline_item.anatomy.root", "descriptionFallback": "Root element. role=\"listitem\", flex row, gap between track and content."}, {"cls": "origam-timeline-item--orientation-horizontal", "descriptionKey": "components.timeline_item.anatomy.horizontal", "descriptionFallback": "Applied when orientation=\"horizontal\". Switches to flex-column layout with horizontal track."}, {"cls": "origam-timeline-item--side-start", "descriptionKey": "components.timeline_item.anatomy.side_start", "descriptionFallback": "Applied when content is on the start side (default)."}, {"cls": "origam-timeline-item--side-end", "descriptionKey": "components.timeline_item.anatomy.side_end", "descriptionFallback": "Applied when content is on the end side (row-reverse layout)."}, {"cls": "origam-timeline-item--alternating", "descriptionKey": "components.timeline_item.anatomy.alternating", "descriptionFallback": "Applied when side=\"alternating\". Even items go to start, odd items to end."}, {"cls": "origam-timeline-item--last", "descriptionKey": "components.timeline_item.anatomy.last", "descriptionFallback": "Applied when isLast=true. Removes bottom padding from content area."}, {"cls": "origam-timeline-item__track", "descriptionKey": "components.timeline_item.anatomy.track", "descriptionFallback": "Track column containing dot and connector."}, {"cls": "origam-timeline-item__dot", "descriptionKey": "components.timeline_item.anatomy.dot", "descriptionFallback": "Circular dot. Color set via intent-resolved CSS custom properties."}, {"cls": "origam-timeline-item__connector", "descriptionKey": "components.timeline_item.anatomy.connector", "descriptionFallback": "Connector line. Hidden on last item when truncateLine is active."}, {"cls": "origam-timeline-item__content", "descriptionKey": "components.timeline_item.anatomy.content", "descriptionFallback": "Content wrapper. flex: 1."}, {"cls": "origam-timeline-item__header", "descriptionKey": "components.timeline_item.anatomy.header", "descriptionFallback": "Header row with title and subtitle."}, {"cls": "origam-timeline-item__title", "descriptionKey": "components.timeline_item.anatomy.title", "descriptionFallback": "Title text element."}, {"cls": "origam-timeline-item__subtitle", "descriptionKey": "components.timeline_item.anatomy.subtitle", "descriptionFallback": "Subtitle text element."}, {"cls": "origam-timeline-item__body", "descriptionKey": "components.timeline_item.anatomy.body", "descriptionFallback": "Body text area. Only rendered when description or body slot is present."}], "svgDesc": "Schematic of the TimelineItem component with 7 numbered internal parts.", "svgTitle": "Anatomy of OrigamTimelineItem", "rootClass": "origam-timeline-item", "figcaption": "Anatomy of <code>&lt;origam-timeline-item&gt;</code> — 7 internal parts. The track holds the dot and connector; the content area holds the header (title + subtitle) and the body.", "svgViewBox": "0 0 640 260"}, "cssVars": [{"name": "--origam-timeline---gap", "defaultValue": "14px", "descriptionKey": "components.timeline_item.css_vars.gap", "descriptionFallback": "Gap between the track and the content area."}, {"name": "--origam-timeline---track-width", "defaultValue": "24px", "descriptionKey": "components.timeline_item.css_vars.track_width", "descriptionFallback": "Fixed width of the track column (holds dot + connector)."}, {"name": "--origam-timeline---dot-size", "defaultValue": "12px", "descriptionKey": "components.timeline_item.css_vars.dot_size", "descriptionFallback": "Diameter of the timeline dot circle."}, {"name": "--origam-timeline-item---dot-bg", "defaultValue": "var(--origam-timeline---dot-bg)", "descriptionKey": "components.timeline_item.css_vars.dot_bg", "descriptionFallback": "Per-item dot background color. Set via intent-resolved CSS custom property on the dot element style."}, {"name": "--origam-timeline-item---dot-color", "defaultValue": "var(--origam-timeline---dot-color)", "descriptionKey": "components.timeline_item.css_vars.dot_color", "descriptionFallback": "Per-item dot foreground (icon) color. Set via intent-resolved CSS custom property."}, {"name": "--origam-timeline---dot-border-width", "defaultValue": "2px", "descriptionKey": "components.timeline_item.css_vars.dot_border_width", "descriptionFallback": "Border width of the dot circle (separates dot from background)."}, {"name": "--origam-timeline---connector-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.timeline_item.css_vars.connector_color", "descriptionFallback": "Color of the connector line between dots."}, {"name": "--origam-timeline---connector-thickness", "defaultValue": "1px", "descriptionKey": "components.timeline_item.css_vars.connector_thickness", "descriptionFallback": "Thickness of the connector line."}, {"name": "--origam-timeline---title-font-size", "defaultValue": "0.875rem", "descriptionKey": "components.timeline_item.css_vars.title_font_size", "descriptionFallback": "Font size of the item title text."}, {"name": "--origam-timeline---title-font-weight", "defaultValue": "600", "descriptionKey": "components.timeline_item.css_vars.title_font_weight", "descriptionFallback": "Font weight of the item title text."}, {"name": "--origam-timeline---subtitle-font-size", "defaultValue": "0.75rem", "descriptionKey": "components.timeline_item.css_vars.subtitle_font_size", "descriptionFallback": "Font size of the subtitle and body text."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.timeline_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.timeline_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.timeline_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.timeline_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.timeline_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.timeline_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.timeline_item.playground.title", "defaultValue": "Event title", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.timeline_item.playground.subtitle", "defaultValue": "2024-01-10", "labelFallback": "Subtitle"}, {"kind": "text", "prop": "description", "labelKey": "components.timeline_item.playground.description", "defaultValue": "Event description text.", "labelFallback": "Description"}, {"kind": "select", "prop": "intent", "options": [{"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.timeline_item.playground.intent", "defaultValue": "primary", "labelFallback": "Intent"}, {"kind": "select", "prop": "icon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-check", "value": "mdi-check"}, {"label": "mdi-clock", "value": "mdi-clock"}, {"label": "mdi-alert", "value": "mdi-alert"}, {"label": "mdi-star", "value": "mdi-star"}], "labelKey": "components.timeline_item.playground.icon", "defaultValue": "", "labelFallback": "Icon"}, {"kind": "select", "prop": "side", "options": [{"label": "start", "value": "start"}, {"label": "end", "value": "end"}], "labelKey": "components.timeline_item.playground.side", "defaultValue": "start", "labelFallback": "Side"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3a470dd5-1927-4abc-8d4f-2c0883011ae7', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'title', 'Title', 'Data Display', NULL, 'mdi-format-header-1', 'components.catalog.title.description', 'Polymorphic heading with configurable tag (h1–h6 or any block element) and density-driven typography tokens.', NULL, NULL, 'origam-title', NULL, 'packages/ds/src/components/Title/OrigamTitle.vue', 'origam', NULL, NULL, '/stories/?story=components-title--design', '/docs/components/Title/OrigamTitle.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.title.a11y.heading_level_note", "noteFallback": "Always choose a tag value that fits the document heading hierarchy (h1 for the page title, h2 for sections, etc.). Skipping heading levels (h1 → h3) impairs screen reader navigation."}, {"noteKey": "components.title.a11y.vcontrast_note", "noteFallback": "The vContrast directive automatically adjusts the text color for sufficient contrast against the background. Do not suppress it without verifying WCAG AA compliance manually."}, {"noteKey": "components.title.a11y.color_note", "noteFallback": "When setting color or bgColor, verify that the contrast ratio meets WCAG 2.1 AA (≥ 4.5:1 for normal text). The vContrast directive assists but does not guarantee compliance for every color combination."}], "roles": ["heading (native HTML)"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-title---color", "descriptionKey": "components.title.tokens.color", "descriptionFallback": "Default heading text color."}, {"type": "fontFamily", "value": "var(--origam-font__family---sans)", "tokenPath": "--origam-title---font-family", "descriptionKey": "components.title.tokens.font_family", "descriptionFallback": "Heading font family."}, {"type": "fontWeight", "value": "var(--origam-font__weight---semibold)", "tokenPath": "--origam-title---font-weight", "descriptionKey": "components.title.tokens.font_weight", "descriptionFallback": "Heading font weight."}, {"type": "dimension", "value": "var(--origam-font__size---xl)", "tokenPath": "--origam-title---font-size-md", "descriptionKey": "components.title.tokens.font_size_md", "descriptionFallback": "Font size for density=default."}, {"type": "dimension", "value": "var(--origam-font__size---3xl)", "tokenPath": "--origam-title---font-size-xl", "descriptionKey": "components.title.tokens.font_size_xl", "descriptionFallback": "Font size for density=comfortable."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-title---font-size-xs", "descriptionKey": "components.title.tokens.font_size_xs", "descriptionFallback": "Font size for density=compact."}, {"type": "dimension", "value": "var(--origam-font__letterSpacing---tight)", "tokenPath": "--origam-title---letter-spacing", "descriptionKey": "components.title.tokens.letter_spacing", "descriptionFallback": "Heading letter-spacing."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"544\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"52\" y=\"90\" font-size=\"28\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-weight=\"700\" font-family=\"sans-serif\">Page Title</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"40\" x2=\"80\" y2=\"22\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-title (tag=h1 default)</text>\n  <text x=\"300\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">density: compact → xs · default → md · comfortable → xl</text>\n", "code": "<!-- root: polymorphic heading, h1 by default -->\n<component\n  :is=\"tag\"\n  :id=\"id\"\n  v-contrast\n  class=\"origam-title\"\n  :class=\"[densityClasses, colorClasses, borderClasses, paddingClasses, marginClasses]\"\n  :style=\"[colorStyles, borderStyles, paddingStyles, marginStyles]\"\n>\n  <slot v-if=\"hasContent\" name=\"default\">{{ text }}</slot>\n</component>", "legend": [{"cls": ".origam-title", "num": 1, "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. Renders as <h1> by default (overridable via tag prop). Uses vContrast directive for automatic text color contrast. Three density modifier classes control font size: --density-compact, --density-default, --density-comfortable."}], "classes": [{"cls": "origam-title", "descriptionKey": "components.title.anatomy.root", "descriptionFallback": "Root element. font-family, font-weight, letter-spacing, line-height come from tokens."}, {"cls": "origam-title--density-compact", "descriptionKey": "components.title.anatomy.density_compact", "descriptionFallback": "Applied when density=\"compact\". font-size: var(--origam-title---font-size-xs)."}, {"cls": "origam-title--density-default", "descriptionKey": "components.title.anatomy.density_default", "descriptionFallback": "Applied when density=\"default\". font-size: var(--origam-title---font-size-md)."}, {"cls": "origam-title--density-comfortable", "descriptionKey": "components.title.anatomy.density_comfortable", "descriptionFallback": "Applied when density=\"comfortable\". font-size: var(--origam-title---font-size-xl)."}], "svgDesc": "Schematic of the Title component — single root element with density class.", "svgTitle": "Anatomy of OrigamTitle", "rootClass": "origam-title", "figcaption": "Anatomy of <code>&lt;origam-title&gt;</code> — a single polymorphic element ①. Font size is controlled by <code>density</code> via three token tiers.", "svgViewBox": "0 0 600 160"}, "cssVars": [{"name": "--origam-title---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.title.css_vars.color", "descriptionFallback": "Default heading text color."}, {"name": "--origam-title---font-family", "defaultValue": "{font.family.sans}", "descriptionKey": "components.title.css_vars.font_family", "descriptionFallback": "Heading font family."}, {"name": "--origam-title---font-weight", "defaultValue": "{font.weight.semibold}", "descriptionKey": "components.title.css_vars.font_weight", "descriptionFallback": "Heading font weight."}, {"name": "--origam-title---letter-spacing", "defaultValue": "{font.letterSpacing.tight}", "descriptionKey": "components.title.css_vars.letter_spacing", "descriptionFallback": "Heading letter-spacing."}, {"name": "--origam-title---line-height", "defaultValue": "{font.lineHeight.tight}", "descriptionKey": "components.title.css_vars.line_height", "descriptionFallback": "Heading line-height."}, {"name": "--origam-title---font-size-xs", "defaultValue": "{font.size.md}", "descriptionKey": "components.title.css_vars.font_size_xs", "descriptionFallback": "Font size for density=\"compact\"."}, {"name": "--origam-title---font-size-md", "defaultValue": "{font.size.xl}", "descriptionKey": "components.title.css_vars.font_size_md", "descriptionFallback": "Font size for density=\"default\"."}, {"name": "--origam-title---font-size-xl", "defaultValue": "{font.size.3xl}", "descriptionKey": "components.title.css_vars.font_size_xl", "descriptionFallback": "Font size for density=\"comfortable\"."}, {"name": "--origam-title---margin-block-start", "defaultValue": "{space.0}", "descriptionKey": "components.title.css_vars.margin_block_start", "descriptionFallback": "Top margin override (zeroed by default — control spacing via the margin prop)."}, {"name": "--origam-title---margin-block-end", "defaultValue": "{space.0}", "descriptionKey": "components.title.css_vars.margin_block_end", "descriptionFallback": "Bottom margin override (zeroed by default)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.title.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.title.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.title.exposed.id", "descriptionFallback": "Unique style-sheet ID (aliased to styleId internally to avoid shadowing the id prop)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.title.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.title.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.title.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "tag", "options": [{"label": "h1", "value": "h1"}, {"label": "h2", "value": "h2"}, {"label": "h3", "value": "h3"}, {"label": "h4", "value": "h4"}, {"label": "h5", "value": "h5"}, {"label": "h6", "value": "h6"}, {"label": "p", "value": "p"}], "labelKey": "components.title.playground.tag", "defaultValue": "h1", "labelFallback": "Tag (heading level)"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.title.playground.density", "defaultValue": "default", "labelFallback": "Density (font size)"}, {"kind": "select", "prop": "color", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.title.playground.color", "defaultValue": "", "labelFallback": "Color"}], "defaultSlotContent": "Page Title"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a26a0327-02d6-4e04-be89-3c312aa40ed6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'toolbar', 'Toolbar', 'Layout & Structure', NULL, 'mdi-toolbar', 'components.catalog.toolbar.description', 'Horizontal bar hosting a title, prepend/append action zones and content. Supports collapse, flat and floating modes with density and elevation control.', NULL, NULL, 'origam-toolbar', NULL, 'packages/ds/src/components/Toolbar/OrigamToolbar.vue', 'origam', NULL, NULL, '/stories/?story=components-toolbar--design', '/docs/components/Toolbar/OrigamToolbar.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.toolbar.a11y.landmark", "noteFallback": "When rendered as <header> (default tag), the toolbar acts as a ARIA banner landmark. Ensure only one banner per page."}, {"noteKey": "components.toolbar.a11y.icon_btns", "noteFallback": "Icon-only buttons inside the toolbar must carry an aria-label."}], "roles": ["banner"], "keyboard": [{"key": "Tab", "actionKey": "components.toolbar.a11y.key_tab", "actionFallback": "Moves focus through interactive children (buttons, links) in the toolbar."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-toolbar---background", "descriptionKey": "components.toolbar.tokens.background", "descriptionFallback": "Default toolbar background."}, {"type": "dimension", "value": "var(--origam-toolbar---height-default, var(--origam-space---14))", "tokenPath": "--origam-toolbar---height", "descriptionKey": "components.toolbar.tokens.height", "descriptionFallback": "Default height (56px)."}, {"type": "dimension", "value": "var(--origam-space---10)", "tokenPath": "--origam-toolbar---height-compact", "descriptionKey": "components.toolbar.tokens.height_compact", "descriptionFallback": "Compact density height."}, {"type": "shadow", "value": "var(--origam-shadow---sm)", "tokenPath": "--origam-toolbar---box-shadow", "descriptionKey": "components.toolbar.tokens.box_shadow", "descriptionFallback": "Default shadow."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-toolbar---transition-duration", "descriptionKey": "components.toolbar.tokens.transition_duration", "descriptionFallback": "Height/shadow transition duration."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"40\" width=\"660\" height=\"56\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"96\" width=\"660\" height=\"4\" rx=\"0\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.08))\"/>\n  <rect x=\"28\" y=\"48\" width=\"52\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"54\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"88\" y=\"56\" width=\"120\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"148\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">title</text>\n  <rect x=\"216\" y=\"48\" width=\"288\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.20))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"360\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">content</text>\n  <rect x=\"612\" y=\"48\" width=\"60\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"642\" y=\"72\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <circle cx=\"28\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"54\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"54\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"148\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"360\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"360\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"642\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"642\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <line x1=\"28\" y1=\"39\" x2=\"28\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"50\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-toolbar</text>\n", "code": "<component :is=\"tag\" class=\"origam-toolbar\">\n  <slot name=\"default\">\n    <div class=\"origam-toolbar__wrapper\">\n      <!-- prepend zone (nav icon, back btn) -->\n      <div v-if=\"hasPrepend\" class=\"origam-toolbar__prepend\">\n        <slot name=\"prepend\" />\n      </div>\n      <!-- title -->\n      <div v-if=\"hasTitle\" class=\"origam-toolbar__title\">\n        <slot name=\"title\">\n          <origam-title :text=\"title\" />\n        </slot>\n      </div>\n      <!-- flexible content area -->\n      <div class=\"origam-toolbar__content\">\n        <slot name=\"content\" />\n      </div>\n      <!-- append zone (action buttons, overflow) -->\n      <div v-if=\"hasAppend\" class=\"origam-toolbar__append\">\n        <slot name=\"append\" />\n      </div>\n    </div>\n  </slot>\n</component>", "legend": [{"cls": ".origam-toolbar", "num": 1, "descriptionKey": "components.toolbar.anatomy.root", "descriptionFallback": "Root element. Renders as <code>&lt;header&gt;</code> by default. Hosts the box-shadow and z-index."}, {"cls": ".origam-toolbar__prepend", "num": 2, "descriptionKey": "components.toolbar.anatomy.prepend", "descriptionFallback": "Leading zone. Rendered only when the #prepend slot has content. Margin-end: auto pushes the title to the right."}, {"cls": ".origam-toolbar__title", "num": 3, "descriptionKey": "components.toolbar.anatomy.title", "descriptionFallback": "Title zone. Contains an <code>OrigamTitle</code> by default, or the #title slot."}, {"cls": ".origam-toolbar__content", "num": 4, "descriptionKey": "components.toolbar.anatomy.content", "descriptionFallback": "Flexible center area. flex-grow: 1 so it absorbs all remaining space."}, {"cls": ".origam-toolbar__append", "num": 5, "descriptionKey": "components.toolbar.anatomy.append", "descriptionFallback": "Trailing zone. Rendered only when the #append slot has content. Margin-start: auto pushes it to the far right."}], "classes": [{"cls": "origam-toolbar", "descriptionKey": "components.toolbar.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-toolbar__wrapper", "descriptionKey": "components.toolbar.anatomy.wrapper", "descriptionFallback": "Inner flex row container."}, {"cls": "origam-toolbar__prepend", "descriptionKey": "components.toolbar.anatomy.prepend", "descriptionFallback": "Leading slot host."}, {"cls": "origam-toolbar__title", "descriptionKey": "components.toolbar.anatomy.title", "descriptionFallback": "Title slot host."}, {"cls": "origam-toolbar__content", "descriptionKey": "components.toolbar.anatomy.content", "descriptionFallback": "Flexible content area."}, {"cls": "origam-toolbar__append", "descriptionKey": "components.toolbar.anatomy.append", "descriptionFallback": "Trailing slot host."}], "svgDesc": "Schematic of the Toolbar component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamToolbar", "rootClass": "origam-toolbar", "figcaption": "Anatomy of <code>&lt;origam-toolbar&gt;</code> — 5 internal parts. The <code>__wrapper</code> arranges prepend, title, content and append in a row; the optional shadow line ① marks the bottom edge.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-toolbar---background", "defaultValue": "{color.surface.default}", "descriptionKey": "components.toolbar.css_vars.background", "descriptionFallback": "Toolbar background color."}, {"name": "--origam-toolbar---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.toolbar.css_vars.color", "descriptionFallback": "Foreground (text/icon) color."}, {"name": "--origam-toolbar---height", "defaultValue": "{space.14}", "descriptionKey": "components.toolbar.css_vars.height", "descriptionFallback": "Default height (56px). Overridden per density variant."}, {"name": "--origam-toolbar---height-compact", "defaultValue": "{space.10}", "descriptionKey": "components.toolbar.css_vars.height_compact", "descriptionFallback": "Height in density=\"compact\" mode (40px)."}, {"name": "--origam-toolbar---height-prominent", "defaultValue": "{space.20}", "descriptionKey": "components.toolbar.css_vars.height_prominent", "descriptionFallback": "Height in density=\"prominent\" mode (80px)."}, {"name": "--origam-toolbar---box-shadow", "defaultValue": "{shadow.sm}", "descriptionKey": "components.toolbar.css_vars.box_shadow", "descriptionFallback": "Box shadow. Set to none via the flat prop."}, {"name": "--origam-toolbar---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.toolbar.css_vars.transition_duration", "descriptionFallback": "Transition duration for height, transform, and box-shadow."}, {"name": "--origam-toolbar---z-index", "defaultValue": "{zIndex.fixed}", "descriptionKey": "components.toolbar.css_vars.z_index", "descriptionFallback": "Z-index of the toolbar when position is fixed or sticky."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.toolbar.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.toolbar.exposed.css", "descriptionFallback": "Reactive CSS string for the computed toolbar styles (used by DefaultsProvider)."}, {"name": "id", "type": "string", "descriptionKey": "components.toolbar.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.toolbar.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.toolbar.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.toolbar.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.toolbar.playground.title", "defaultValue": "My App", "labelFallback": "Title"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(surface)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.toolbar.playground.bg_color", "defaultValue": "", "labelFallback": "Background"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "prominent", "value": "prominent"}], "labelKey": "components.toolbar.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "select", "prop": "elevation", "options": [{"label": "0", "value": "0"}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}, {"label": "8", "value": "8"}], "labelKey": "components.toolbar.playground.elevation", "defaultValue": "2", "labelFallback": "Elevation"}, {"kind": "switch", "prop": "flat", "labelKey": "components.toolbar.playground.flat", "defaultValue": false, "labelFallback": "Flat"}, {"kind": "switch", "prop": "floating", "labelKey": "components.toolbar.playground.floating", "defaultValue": false, "labelFallback": "Floating"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "pill", "value": "pill"}], "labelKey": "components.toolbar.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}]}, "previewVariants": [{"label": "default", "props": {"title": "App", "elevation": "2"}}, {"label": "flat", "props": {"flat": true, "title": "Flat"}}, {"label": "primary", "props": {"flat": true, "color": "white", "title": "Primary", "bgColor": "primary"}}, {"label": "compact", "props": {"title": "Compact", "density": "compact"}}, {"label": "rounded", "props": {"title": "Rounded", "rounded": "lg", "elevation": "2"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb2cf80f-7fe2-49ea-afb8-76a1a7ed7ab1', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'tooltip', 'Tooltip', 'Overlay & Surface', NULL, 'mdi-tooltip-text', 'components.catalog.tooltip.description', 'Contextual floating label anchored to an activator element. Appears on hover/focus, auto-positioned via location strategy.', NULL, NULL, 'origam-tooltip', NULL, 'packages/ds/src/components/Tooltip/OrigamTooltip.vue', 'origam', NULL, NULL, '/stories/?story=components-tooltip--design', '/docs/components/Tooltip/OrigamTooltip.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.tooltip.a11y.aria_describedby", "noteFallback": "The activator element receives aria-describedby pointing to the tooltip id so screen readers announce the tooltip text."}, {"noteKey": "components.tooltip.a11y.role", "noteFallback": "role=\"tooltip\" is applied directly on the OrigamOverlay element (not just the content div) so the association is unambiguous."}, {"noteKey": "components.tooltip.a11y.reduced_motion", "noteFallback": "Transitions are disabled under prefers-reduced-motion: reduce."}], "roles": ["tooltip"], "keyboard": [{"key": "Tab / Shift+Tab", "actionKey": "components.tooltip.a11y.key_focus", "actionFallback": "Focusing the activator opens the tooltip. Blurring closes it."}, {"key": "Escape", "actionKey": "components.tooltip.a11y.key_escape", "actionFallback": "Closes the tooltip if it was opened via keyboard focus."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__neutral---800)", "tokenPath": "--origam-tooltip---background-color", "descriptionKey": "components.tooltip.tokens.background_color", "descriptionFallback": "Dark inverse background for contrast in both themes."}, {"type": "color", "value": "var(--origam-color__text---inverse)", "tokenPath": "--origam-tooltip---color", "descriptionKey": "components.tooltip.tokens.color", "descriptionFallback": "Inverse text color (white on dark surface)."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-tooltip---border-radius", "descriptionKey": "components.tooltip.tokens.border_radius", "descriptionFallback": "Corner radius."}, {"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tooltip---transition-duration", "descriptionKey": "components.tooltip.tokens.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"type": "number", "value": "var(--origam-zIndex---tooltip)", "tokenPath": "--origam-tooltip---z-index", "descriptionKey": "components.tooltip.tokens.z_index", "descriptionFallback": "Z-index layer."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"250\" y=\"130\" width=\"200\" height=\"40\" rx=\"6\" fill=\"var(--origam-color__neutral---800, #1f1333)\"/>\n  <text x=\"350\" y=\"154\" font-size=\"11\" fill=\"var(--origam-color__text---inverse, #fff)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Tooltip text</text>\n  <polygon points=\"350,118 340,130 360,130\" fill=\"var(--origam-color__neutral---800, #1f1333)\"/>\n  <rect x=\"300\" y=\"60\" width=\"100\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">activator</text>\n  <circle cx=\"258\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"258\" y=\"142\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"350\" cy=\"138\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"142\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"350\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<origam-overlay role=\"tooltip\" :id=\"id\" class=\"origam-tooltip\" …>\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\" />\n  </template>\n  <template #default>\n    <!-- visible surface -->\n    <div class=\"origam-tooltip__content\">\n      <slot name=\"default\">\n        <span>{{ text }}</span>\n      </slot>\n    </div>\n  </template>\n</origam-overlay>", "legend": [{"cls": ".origam-tooltip", "num": 1, "descriptionKey": "components.tooltip.anatomy.root", "descriptionFallback": "Root overlay element — transparent, zero-size. Wraps OrigamOverlay; positions via location strategy. role=\"tooltip\" set explicitly."}, {"cls": ".origam-tooltip__content", "num": 2, "descriptionKey": "components.tooltip.anatomy.content", "descriptionFallback": "Visible content surface. Background: neutral.800 (dark inverse). Contains the text or #default slot."}, {"cls": "[activator]", "num": 3, "descriptionKey": "components.tooltip.anatomy.activator", "descriptionFallback": "External activator element projected via #activator slot. Receives aria-describedby pointing to the tooltip id."}], "classes": [{"cls": "origam-tooltip", "descriptionKey": "components.tooltip.anatomy.root", "descriptionFallback": "Root overlay element."}, {"cls": "origam-tooltip__content", "descriptionKey": "components.tooltip.anatomy.content", "descriptionFallback": "Visible floating pill with dark background."}], "svgDesc": "Schematic of the Tooltip overlay with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamTooltip", "rootClass": "origam-tooltip", "figcaption": "Anatomy of <code>&lt;origam-tooltip&gt;</code> — overlay wraps a content div ① with the text ②; the activator ③ (any element) triggers visibility.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-tooltip---background-color", "defaultValue": "{color.neutral.800}", "descriptionKey": "components.tooltip.css_vars.background_color", "descriptionFallback": "Tooltip background. Dark inverse surface for contrast in both themes."}, {"name": "--origam-tooltip---color", "defaultValue": "{color.text.inverse}", "descriptionKey": "components.tooltip.css_vars.color", "descriptionFallback": "Tooltip text color."}, {"name": "--origam-tooltip---font-size", "defaultValue": "{font.size.sm}", "descriptionKey": "components.tooltip.css_vars.font_size", "descriptionFallback": "Font size of the tooltip label."}, {"name": "--origam-tooltip---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.tooltip.css_vars.border_radius", "descriptionFallback": "Corner radius of the tooltip pill."}, {"name": "--origam-tooltip---max-width", "defaultValue": "300px", "descriptionKey": "components.tooltip.css_vars.max_width", "descriptionFallback": "Maximum width before tooltip text wraps."}, {"name": "--origam-tooltip---z-index", "defaultValue": "{zIndex.tooltip}", "descriptionKey": "components.tooltip.css_vars.z_index", "descriptionFallback": "Z-index of the tooltip overlay."}, {"name": "--origam-tooltip---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.tooltip.css_vars.transition_duration", "descriptionFallback": "Enter/leave transition duration."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tooltip.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to OrigamOverlay."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tooltip.exposed.css", "descriptionFallback": "Reactive CSS string for computed tooltip styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tooltip.exposed.id", "descriptionFallback": "Unique ID for this tooltip instance (referenced by aria-describedby on the activator)."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tooltip.exposed.load", "descriptionFallback": "Injects the computed style sheet."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tooltip.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tooltip.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}, {"name": "styleId", "type": "string", "descriptionKey": "components.tooltip.exposed.style_id", "descriptionFallback": "Unique style-sheet ID scoping injected CSS rules."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.tooltip.playground.text", "defaultValue": "This is a tooltip", "labelFallback": "Text"}, {"kind": "select", "prop": "location", "options": [{"label": "top", "value": "top"}, {"label": "bottom", "value": "bottom"}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "top start", "value": "top start"}, {"label": "top end", "value": "top end"}, {"label": "bottom start", "value": "bottom start"}, {"label": "bottom end", "value": "bottom end"}], "labelKey": "components.tooltip.playground.location", "defaultValue": "top", "labelFallback": "Location"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(inverse dark)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.tooltip.playground.bg_color", "defaultValue": "", "labelFallback": "Background"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4c4d0ea2-06f9-4135-aada-c11d9f0cfc96', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'component', 'transition', 'Transition', 'Utilities & Providers', NULL, 'mdi-transition', 'components.catalog.transition.description', 'CSS-driven Vue transition wrappers. The family includes Fade, SlideX, SlideY, ExpandX, ExpandY, ScaleRotate and a generic Transition component. All are prefers-reduced-motion aware.', NULL, NULL, 'origam-transition', NULL, 'packages/ds/src/components/Transition/OrigamTransition.vue', 'origam', NULL, NULL, '/stories/?story=components-transition--design', '/docs/components/Transition/OrigamTransition.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.transition.a11y.reduced_motion", "noteFallback": "All Origam transition components detect prefers-reduced-motion: reduce and disable the animation (disabled=true) automatically. Content still appears/disappears instantly."}, {"noteKey": "components.transition.a11y.no_role", "noteFallback": "Transition wrappers are transparent to the accessibility tree — they add no ARIA roles or attributes. Only the slotted content is announced by screen readers."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"180\" y=\"84\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">enter-active</text>\n  <rect x=\"380\" y=\"40\" width=\"280\" height=\"80\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"5 3\" opacity=\"0.5\"/>\n  <text x=\"520\" y=\"84\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">leave-active</text>\n  <circle cx=\"48\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"388\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"388\" y=\"52\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <text x=\"350\" y=\"80\" font-size=\"20\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\">→</text>\n", "code": "<!-- generic wrapper — delegates to <transition> or <transition-group> -->\n<component :is=\"group ? ''transition-group'' : ''transition''\" :name=\"name\" v-bind=\"transitionProps\">\n  <slot name=\"default\" />\n</component>", "legend": [{"cls": "[enter-active]", "num": 1, "descriptionKey": "components.transition.anatomy.enter", "descriptionFallback": "The entering element receives the transition CSS class (e.g. origam-transition--fade-enter-active)."}, {"cls": "[leave-active]", "num": 2, "descriptionKey": "components.transition.anatomy.leave", "descriptionFallback": "The leaving element receives the leave-active class and exits. In out-in mode this completes before the enter starts."}], "classes": [{"cls": "origam-transition--fade", "descriptionKey": "components.transition.anatomy.fade_cls", "descriptionFallback": "Opacity-only CSS transition class."}, {"cls": "origam-transition--slide-x", "descriptionKey": "components.transition.anatomy.slide_x_cls", "descriptionFallback": "Horizontal slide + fade CSS transition class."}, {"cls": "origam-transition--slide-y", "descriptionKey": "components.transition.anatomy.slide_y_cls", "descriptionFallback": "Vertical slide + fade CSS transition class."}, {"cls": "origam-transition--scale-rotate", "descriptionKey": "components.transition.anatomy.scale_rotate_cls", "descriptionFallback": "Scale + rotate + fade CSS transition class."}], "svgDesc": "Schematic showing transition wrapper over entering and leaving elements.", "svgTitle": "Anatomy of OrigamTransition", "rootClass": "origam-transition", "figcaption": "Anatomy of <code>&lt;origam-transition&gt;</code> — wraps a single child. During a transition, the entering element ① is animated in while the leaving element ② animates out (sequence depends on <code>mode</code>).", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-transition---default-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.transition.css_vars.default_duration", "descriptionFallback": "Default transition duration (300 ms)."}, {"name": "--origam-transition---default-easing", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.transition.css_vars.default_easing", "descriptionFallback": "Default easing function (cubic-bezier)."}, {"name": "--origam-transition---slide-x-distance", "defaultValue": "100%", "descriptionKey": "components.transition.css_vars.slide_x_distance", "descriptionFallback": "Horizontal translate distance for slide-x transition."}, {"name": "--origam-transition---slide-y-distance", "defaultValue": "100%", "descriptionKey": "components.transition.css_vars.slide_y_distance", "descriptionFallback": "Vertical translate distance for slide-y transition."}, {"name": "--origam-transition---scale-from", "defaultValue": "0.95", "descriptionKey": "components.transition.css_vars.scale_from", "descriptionFallback": "Initial scale value for scale-based transitions."}, {"name": "--origam-transition---expand-duration", "defaultValue": "{motion.duration.slow}", "descriptionKey": "components.transition.css_vars.expand_duration", "descriptionFallback": "Duration for expand-x/expand-y transitions (400 ms — slightly slower for layout shifts)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.transition.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to the underlying transition."}], "playground": {"controls": [{"kind": "select", "prop": "name", "options": [{"label": "fade", "value": "origam-transition--fade"}, {"label": "slide-x", "value": "origam-transition--slide-x"}, {"label": "slide-y", "value": "origam-transition--slide-y"}, {"label": "scale-rotate", "value": "origam-transition--scale-rotate"}], "labelKey": "components.transition.playground.name", "defaultValue": "origam-transition--fade", "labelFallback": "Transition"}, {"kind": "select", "prop": "mode", "options": [{"label": "(none)", "value": ""}, {"label": "in-out", "value": "in-out"}, {"label": "out-in", "value": "out-in"}], "labelKey": "components.transition.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.transition.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "group", "labelKey": "components.transition.playground.group", "defaultValue": false, "labelFallback": "Group mode"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
