INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2161ea62-e407-439d-9912-5cf106cda64d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-clipboard', 'useClipboard', NULL, 'Clipboard', 'mdi-clipboard-outline', '', 'Headless clipboard composable. Wraps the modern navigator.clipboard.writeText API with a legacy execCommand fallback. Exposes a self-resetting copied flag so consumers do not need to wire the reset timeout themselves. Never throws — callers branch on the returned boolean.', NULL, 'function useClipboard(options?: IUseClipboardOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6ec108e1-9780-400c-bcce-d4c5d919b8a6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-code', 'useCode', NULL, 'Code', 'mdi-code-tags', '', 'Singleton shiki-powered syntax highlighter. Lazily loads shiki on the first highlight() call to keep the initial bundle small. Bundles only the curated origam language subset and dual light/dark themes so token colours switch via CSS variables without re-tokenising. Caches results in a tiny LRU keyed by (code, lang).', NULL, 'function useCode(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d13f5c2a-74b8-4714-8d33-f0c742caf358', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-color', 'useColor', NULL, 'Commons', 'mdi-palette', '', 'Resolve background and text colors from intent tokens or raw CSS values. Part of the classes-first strategy: tokenised intents emit utility classes, custom hex/rgb values emit inline styles.', NULL, 'function useColor(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('57cdd81f-bb04-4b94-8767-79eeba0c5364', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-color-effect', 'useColorEffect', NULL, 'Commons', 'mdi-palette-swatch', '', 'State-aware (hover / active / disabled) color resolution for components that paint a surface. Resolves bg and fg independently per state axis. Auto-contrasts foreground when only `bgColor` is set. Used by Btn, Card, Chip and ~49 other components.', NULL, 'function useColorEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4798b535-761e-4d72-9f6a-b4e1990dd975', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-command', 'useCommand', NULL, 'CommandPalette', 'mdi-console-line', '', 'Process-wide command palette registry. Uses module-scope state (not provide/inject) so commands can be registered from anywhere — feature code, plugins, background services — without coupling to a Vue tree. Two callers on the same module instance see the exact same reactive list.', NULL, 'function useCommand(): {
