INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0146bde9-ab06-4dfa-8334-60420221aae9', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'composable', 'use-theme', 'useTheme', NULL, 'Theme', 'mdi-theme-light-dark', '', 'Module-level singleton managing the brand theme axis (data-theme attribute) and the color-mode axis (data-mode attribute). Persists both axes to localStorage and reacts to prefers-color-scheme. Every call to useTheme() shares the same refs.', NULL, 'function useTheme(): {
