INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4994a5e-9de2-4405-acbb-3821cc4d572e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '71e05799-a623-48ce-bccb-9554ba560bc0', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a58418d-5004-4445-bf05-6f6b88948fbb', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '71e05799-a623-48ce-bccb-9554ba560bc0', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f136bc6-253f-4eee-8940-b90ad1e30633', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '71e05799-a623-48ce-bccb-9554ba560bc0', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('943dd23f-655f-4721-85f4-c5510a951f50', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fcf61e70-94bd-4a7b-a82b-079b459c6a3d', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b79b0177-ff8d-459b-862a-f2a7bb6b509e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fcf61e70-94bd-4a7b-a82b-079b459c6a3d', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7a0a2af-5cf9-4599-a95c-110e5393ac17', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fcf61e70-94bd-4a7b-a82b-079b459c6a3d', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('38647a2d-cc24-43b7-82c4-ae017766f73a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'a4a633dc-3048-48b7-826a-4eee4c6883e1', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cd8e8b0-993d-4160-983f-03b00bbe4cf8', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'a4a633dc-3048-48b7-826a-4eee4c6883e1', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('472bc9ed-1662-4534-a20f-303f8b09baad', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'a4a633dc-3048-48b7-826a-4eee4c6883e1', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
