INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b818e4cd-42e6-4ad1-94f4-81a61660e7fc', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '51aae445-6fbc-4bea-827c-2a1cd6b49d12', 'props', '{ aspectRatio?: string | number }', true, NULL, '', 'Object carrying an optional aspectRatio value. Accepts a numeric ratio (1.777 for 16:9), a division expression string ("16/9"), or is left undefined to use window.innerWidth / window.innerHeight as the ratio.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('67b5000b-1a11-4681-9e1d-fc606bebe795', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9160bbf4-c6af-43e5-bc69-0ea2cc0d9b8e', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
