INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66286f4a-bee8-48d1-b2ea-b741284404eb', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '7d68247e-72f1-490d-91a4-a84214aff9a0', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9794b78a-daa3-4838-b22d-7a325cc5b00a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '7d68247e-72f1-490d-91a4-a84214aff9a0', 'setView', '(view: TCalendarView) => void', false, NULL, '', 'Optional callback invoked by the returned setView proxy. Bind to a v-model:view setter to keep the parent state in sync when the calendar switches views.', 1, false, NULL, NULL);
