INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d7a9a58-bf54-4216-a7bc-667d2203b5d0', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '56629315-f063-474d-96a0-04e0baf0409b', 'select', '(value: boolean, e?: Event) => void', false, NULL, '', 'The group selection callback injected by useGroup. When the link becomes active, this is called with value=true on the next tick. When undefined, the composable becomes a no-op.', 1, false, NULL, NULL);
