INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('13d16389-2cf4-4a10-a82a-5c454da5857b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d867e46-467a-4dcc-adb9-8f4b35f8607f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '831e9b80-9d91-42ed-b1d1-f7fb9fadb79f', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
