INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7fc1a90-c010-46ef-8c40-ca2cff98ec1c', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('57b877ea-a77e-49d6-91fe-722e3758a41f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4882b897-b907-42ed-9208-982963405df0', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea4adf7e-1958-4556-9d3d-f7e755975ee0', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '0bb92ccd-f379-4ef2-b091-718aa5662a38', 'horizontal', 'boolean', false, NULL, '', '', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('86b87bfb-25f9-4e98-9af7-587a3656bd8f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('18c93ab3-d42a-4085-8f58-c2da6a17ed5f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b5567fe5-2caf-426b-ae38-2cce825212a8', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd6382a8-2dc2-4bdc-82c5-b2d122fb3ad9', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6687a020-05ff-4595-adea-7227d08d3cee', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96349e5b-2b3b-4710-a08e-021a93badb7e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1cd9e6b3-5539-4b0e-97bd-80536b4fe79b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
