INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c42884e6-f676-42a1-b486-513aa16800bd', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('674f9435-b1ba-4890-9dfe-80f5788ab2b1', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
