INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('572d66ae-7ff3-4a79-9a41-fd9c68a2d367', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c948acc4-4f06-482e-8e41-f1a3960844f7', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3415c239-8f04-4d14-a564-49ec2b352f0f', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('21c8ac53-9314-48ee-9de6-226b33c8d5f5', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3415c239-8f04-4d14-a564-49ec2b352f0f', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ebb0fd2-e710-42dd-a375-d8f7456fd29b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '0eac7788-d998-4c88-91c6-b14baf7a3868', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dad394c5-fad6-4eb2-96c0-c43b6b505a1f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '0eac7788-d998-4c88-91c6-b14baf7a3868', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0c56ec0-143e-4229-84b3-062287879924', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '20a5243d-9475-483f-a455-2939c1de0683', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4c983363-081b-4227-81ff-7d8d84ad1bb6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '20a5243d-9475-483f-a455-2939c1de0683', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23adea28-5210-4b7d-8a4c-ff62fb5e5bb4', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9dd5874b-b55e-4484-9eee-24c9425828e3', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('639586b8-c466-4de8-8405-2cbea5325048', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9dd5874b-b55e-4484-9eee-24c9425828e3', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a3aca5ec-048f-4b39-ba93-b92a7bc8f110', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9dd5874b-b55e-4484-9eee-24c9425828e3', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('385293a0-2cc9-4d4e-b35c-6a94a72a1176', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9dd5874b-b55e-4484-9eee-24c9425828e3', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
