INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('90cd2f8d-9c7f-47b0-a982-2a44df0b5cae', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1440232f-01ae-4f31-b43c-9da7ed823a12', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd2d2990-75cc-4622-a43d-752b6ec95190', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'd9aa1742-1e19-4ab1-899e-4d5280d5fda8', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2b312477-e0f0-4764-b9fd-e2c3d3eb69d6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'd9aa1742-1e19-4ab1-899e-4d5280d5fda8', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
