INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a36f4306-650d-4d56-8401-a613fd43cf21', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'd9aa1742-1e19-4ab1-899e-4d5280d5fda8', 'transformIn', '(value?: Props[Prop]) => Inner', false, '(v?: Props[Prop]) => v as Inner', '', 'Optional transform applied to the external prop value before exposing it to the component. Useful for converting a string to a number, or normalising null / undefined.', 3, false, NULL, NULL);
