INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c07da483-5742-40cf-a7b5-61e3cda80876', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '276aec82-86f4-49d3-a6d1-ebad15bf2837', 'lineNumbers', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.line_numbers.description', 'Shows a left gutter with line numbers. Pure CSS counter — no JS layout work.', 2, false, NULL, NULL);
