INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d567b6ac-302c-4851-a84b-4a9cd354774e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '276aec82-86f4-49d3-a6d1-ebad15bf2837', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('320b9bcf-e875-47bc-8b71-e65bd59c46c1', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '276aec82-86f4-49d3-a6d1-ebad15bf2837', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
