INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49200b91-63d1-4632-8dad-2dde1f34de98', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '276aec82-86f4-49d3-a6d1-ebad15bf2837', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
