INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2188b0a1-e2d5-40bf-8685-4d189b540a88', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '654cd988-0555-4606-9d12-d3e40fbbc1b3', 'reset', 'string | number', '', 'primitive', NULL, false, 'undefined', 'components.defaults_provider.props.reset.description', 'When set, parent defaults are NOT inherited; the subtree starts from this provider''s defaults only. The value is opaque but useful for DevTools tracing.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b4bd9480-06f2-4ef8-b233-835cc756db08', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '654cd988-0555-4606-9d12-d3e40fbbc1b3', 'root', 'string | number', '', 'primitive', NULL, false, 'undefined', 'components.defaults_provider.props.root.description', 'Marks the provider as a root scope — equivalent to reset but communicates intent: this is the top of a defaults tree, not a mid-tree override.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b3609a7b-133c-49da-8b31-af4c36a665d4', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '654cd988-0555-4606-9d12-d3e40fbbc1b3', 'scoped', 'boolean', '', 'primitive', NULL, false, 'undefined', 'components.defaults_provider.props.scoped.description', 'When true, parent defaults are not merged in — the subtree only sees this provider''s defaults. Same effect as reset but expressed declaratively.', 4, false, NULL, NULL);
