INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('271403e3-0eae-4119-884d-6293c56e9666', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:34.721394+00', '0f71eb4a-f376-4019-b65c-eeea4555706d', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
