INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b006e95f-f861-4393-8011-2ad1ff9d73be', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9160bbf4-c6af-43e5-bc69-0ea2cc0d9b8e', 'audioRef', 'Ref<HTMLAudioElement | undefined>', '', 'Template ref to assign to the native <audio> element. The composable calls .play() and .pause() on it.', 2, false, NULL, NULL);
