INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7fe4f2d5-502d-4c90-896c-f2bd1ce98a3a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fb3fe106-9329-4373-bb74-453209c6c326', 'selectAll', '(value: boolean) => void', '', 'Select or deselect all eligible items according to the active strategy. Strategy page selects only the current page; strategy all selects across all pages.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9c563ba2-2a34-482e-82d9-e3a34b42298a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fb3fe106-9329-4373-bb74-453209c6c326', 'someSelected', 'ComputedRef<boolean>', '', 'True when the selected Set is non-empty. Used to render the indeterminate state on the select-all checkbox.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bf7260b6-04e0-4a39-89ab-55c97b8d215f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fb3fe106-9329-4373-bb74-453209c6c326', 'allSelected', 'ComputedRef<boolean>', '', 'True when all eligible items (non-disabled) are selected according to the active strategy.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b25f0e98-bf33-4841-ad90-86e21ec3c246', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fb3fe106-9329-4373-bb74-453209c6c326', 'showSelectAll', 'ComputedRef<boolean>', '', 'Whether the select-all checkbox should be visible. Always false for the single select strategy.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd1ed9d2-1c7c-46ac-b232-f2c9d493f704', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9c858192-b84e-4f37-ae2e-947fba494252', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('745ca6f3-70ef-47c0-a168-4771341edf20', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a399baca-5460-47ec-899f-b118341dbcd6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9cad79dd-0f69-40f9-90dd-e2d8802cb5bf', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('73b11356-5bcd-4b04-a2c7-b9e3502c355d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'eb88c879-d7da-4fb2-9b5e-396769cc3426', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76176720-c08a-453e-a016-78896c6d6960', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1ae14d0e-deba-439b-9f15-ef782cd79815', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f49940d2-58ef-429d-ab5f-36dceede06f9', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1ae14d0e-deba-439b-9f15-ef782cd79815', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1b5663a2-71da-47fb-9461-93d04a995c4c', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0dd49c19-c49e-4856-882f-c2523e69d426', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ff5fd2b-9318-4370-a000-edf87c34f795', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ff8b8d8-cf23-4bcc-a09d-56cb43e5a1a1', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('822adf4a-3b74-48da-a4c5-7be62ca82e7a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8bb649f1-bf09-4e6d-aba2-737d7267ff5f', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1ae31602-c8e8-4de3-b71c-5ce09bf2ab8a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '831e9b80-9d91-42ed-b1d1-f7fb9fadb79f', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('adba2c66-e26d-4ca7-8816-49a618d47044', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '831e9b80-9d91-42ed-b1d1-f7fb9fadb79f', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f60ede29-90a5-45ec-9528-03cd5124584a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '831e9b80-9d91-42ed-b1d1-f7fb9fadb79f', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('36655b28-ba99-4def-90dd-a7bdf9d32a15', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '831e9b80-9d91-42ed-b1d1-f7fb9fadb79f', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a25fb49d-17ee-469f-81bb-487ab5bfa475', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'b5415b9c-5e23-4032-8515-7ce2630ce632', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('73d68f81-1069-4c44-b566-bf5811355e5e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'b5415b9c-5e23-4032-8515-7ce2630ce632', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('55397511-3e0a-4e5a-93bb-c82888c41f98', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'b5415b9c-5e23-4032-8515-7ce2630ce632', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5677d2c8-0021-443b-90bb-dbc9da882967', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'b5415b9c-5e23-4032-8515-7ce2630ce632', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c075dd7a-face-4fc4-8b8f-7952d373f6e6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '961c919d-efa1-4b94-b012-0b2b70e7a486', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('813a803f-7f4c-4b55-bfe5-58abcc4ac306', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '961c919d-efa1-4b94-b012-0b2b70e7a486', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ffde247e-ebdc-4065-9ed9-ee65e65ea5b5', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '961c919d-efa1-4b94-b012-0b2b70e7a486', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fda35d5e-e030-45b1-8a78-d3bda13dfbbf', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '19192b19-31e8-467a-b019-f9f49d29ab50', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22403c7e-4849-46f5-923c-3deb7cad0a09', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '19192b19-31e8-467a-b019-f9f49d29ab50', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd0db8fd-1da9-4671-9471-1063fc189680', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'abc53b87-27ee-4ca7-b805-b2a0f276696e', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8716c38d-bfc6-4dfe-a191-69bed38aced3', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('61f50e81-a08a-4d88-a3cb-12dd15e7de40', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1fc7703-f29e-4e4a-8671-f8d0b536299b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'e2819519-1b71-47d8-8bbe-fa61a4e81a63', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc3408ab-7c0a-416d-9df0-2abe5aa70e7d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39a8c156-5f69-49c9-a960-5d87b3c285a5', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b55ba77-4c65-4148-84e7-076fb6cabcf6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a5cbdbaa-68a0-462a-b9ab-835acc34cfac', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
