INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('72179a3f-2370-43d9-bd23-5461cef3fa3e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '93f801f9-99db-401c-b94b-5b947e401d5e', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0458b94e-fb17-432a-9b29-4323861753d3', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('874198aa-9cbe-4203-8b43-99ddb394b549', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('94013799-5978-459e-9525-a0d49f1ce301', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('26c773f9-772c-4d12-8e14-46e81f3adf63', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e862f21f-a2fb-495d-ad32-f083322c298b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '1e5cd66b-3273-4a72-90a8-1f30243e1757', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a31ce055-149e-4246-97ce-5366048bb1ec', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'c7e087dd-4992-4e2a-896a-092ebe9bd32a', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96785b4d-8595-48c3-be9a-356c12149c89', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'c7e087dd-4992-4e2a-896a-092ebe9bd32a', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4e631d8a-5960-40d2-9a06-92f4656dc98f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '2d784c10-75f8-442e-a7b9-ccde0e32df1d', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('177c76c7-e9a1-43c8-9fb0-714e92296f27', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '2d784c10-75f8-442e-a7b9-ccde0e32df1d', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8783c56-ea00-4166-82ba-28ba8ae03d93', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '2d784c10-75f8-442e-a7b9-ccde0e32df1d', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4d62a456-339f-4af7-b049-6e4d0cc5c855', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '2d784c10-75f8-442e-a7b9-ccde0e32df1d', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fad78d38-aa09-4d2f-ae24-c45000b56c1b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'acc8c09a-c10a-4565-bbf6-495c962711b6', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cc900d3-4561-4225-a0e8-11049a4eaea0', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e469ce34-cc62-4553-9ed7-76a5774c40b8', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f28a6901-7112-4e9b-8349-5da852163f0d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fa88ab42-0204-4bde-8659-edef71450e44', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f5950c13-7687-40bc-a57a-afff615f0e4e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b772f3b9-567d-4f0a-b34f-3f2298bd3d98', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '9f3c5803-cf15-4e93-8c54-3ce3bd01c44c', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b917b474-a7cf-4e02-a100-be44fff3a98b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3415c239-8f04-4d14-a564-49ec2b352f0f', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('96e299e2-2197-460c-8dbd-343fb4cb2098', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3415c239-8f04-4d14-a564-49ec2b352f0f', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a6825b43-8ab1-4fa7-85b2-3f7cfe9a6e82', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '0146bde9-ab06-4dfa-8334-60420221aae9', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
