INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e7c7872f-e3a8-4a47-93fa-da3806526e93', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '6e0dec85-a9a7-4ef7-b9fa-5f07c1e5a619', 'addMovement', '(e: TouchEvent) => void', '', 'Record a touchstart or touchmove event sample. Each touch point is tracked independently. Call this on every touchmove to build a time-stamped sample history.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f47a4d01-e69b-479b-9335-e43874d9f777', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '6e0dec85-a9a7-4ef7-b9fa-5f07c1e5a619', 'endTouch', '(e: TouchEvent) => void', '', 'Clear the circular buffer for all changed touches. Call at touchstart before starting a new gesture to discard leftover samples from a previous interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23d32188-20ab-4840-ba58-36304139becc', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '6e0dec85-a9a7-4ef7-b9fa-5f07c1e5a619', 'getVelocity', '(id: number) => { x: number; y: number; direction: string }', '', 'Compute the velocity vector for the given touch identifier from the recent sample history. Returns px/ms values for x and y axes and the dominant direction string. Throws if no samples are found for the id.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea87301d-4924-473b-b0f0-c8d1242bdc6f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '98cce73f-3c6c-4449-b2c1-6a9d5a69d2a8', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('25ac7c36-61df-4464-bd3f-a005f28cb1fd', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '98cce73f-3c6c-4449-b2c1-6a9d5a69d2a8', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('77fa70c5-975d-40c2-a881-1b0207d6311c', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '98cce73f-3c6c-4449-b2c1-6a9d5a69d2a8', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e9415ee1-165e-4eec-a40a-5acb9fae579a', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('41dfa8f0-1bc6-4007-83fa-46cad8400c22', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e9e6c86e-af6d-4c92-bd67-644c53f0e98d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('58579324-af2f-4ec8-94a9-b20c7301449e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a6095265-d001-4f1c-9c3d-7ce49c607254', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('260b30f0-ca7f-407e-8e32-6937984fbfe9', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d0e04ccb-2ecc-4b9f-a712-85cd698f61e9', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b88d5ed4-e157-43d4-bf7c-cca3324b7d95', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b759371-c795-48da-a3ca-d8912325ce58', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '13f755d1-2be8-4226-b590-cc0a1d2eaae7', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4114bf63-7f58-44e2-9b3b-47810945326d', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'd9aa1742-1e19-4ab1-899e-4d5280d5fda8', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a80368a4-4db5-4153-8d08-93950f9cf567', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3df8102d-9c82-4ca7-92b0-21ff42faa53b', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('de38618d-1988-4fa3-8fdb-0eb845304f5e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3df8102d-9c82-4ca7-92b0-21ff42faa53b', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6d58aa70-eee3-4bc8-84fb-d93a14b4e119', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '3df8102d-9c82-4ca7-92b0-21ff42faa53b', 'uninstall', '() => void', '', 'Remove the injected layer and disconnect the MutationObserver if active. Called automatically on scope dispose.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6f26daa9-aafc-4e46-98c0-d6b045bc35f5', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '90c76e91-2e6c-4065-85fe-8327ff7a237e', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('adb2775b-3576-4345-87d7-3658283da8ed', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '90c76e91-2e6c-4065-85fe-8327ff7a237e', 'isComputing', 'Ref<boolean>', '', 'True while the fetch + decode round-trip is in progress. Use to render a skeleton or loading indicator.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('22149f5e-276b-4d10-b537-89a2ba73231f', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '90c76e91-2e6c-4065-85fe-8327ff7a237e', 'error', 'Ref<Error | null>', '', 'Captures fetch errors (non-2xx response), decode errors (corrupt / unsupported audio), and OfflineAudioContext unavailability. null when no error.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('156a3a30-e35a-4463-ab31-ce3b9d84902e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '90c76e91-2e6c-4065-85fe-8327ff7a237e', 'compute', '() => Promise<void>', '', 'Manually trigger a recomputation. Normally not needed — the composable re-runs automatically when srcRef changes. Useful for retry-on-error flows.', 3, false, NULL, NULL);
