INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae347a50-d34b-4222-b54f-8ce539c8837e', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'b4e4db3d-fd05-4d1d-a5ef-76eab2347138', 'offline', 'types.detail.empty_state_preset.offline', 'No network connection detected. The CTA typically offers offline-mode or a reconnect action.', 3, false, NULL, NULL);
