INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ef33840-5d9c-496e-8441-7cf38b333840', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', 'fe705c70-4b1e-41f6-a3a4-d5727a0079f0', 'md', 'types.detail.empty_state_size.md', 'Default — balanced icon size, standard font sizes. Suitable for full-page section empty states.', 0, false, NULL, NULL);
