INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1f8741c-ad57-49f3-a374-4021177733c7', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8da9385d-63e5-49d4-ab79-98abff4a73b6', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('950ad8bc-eaac-4b99-af97-b979f93390be', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8da9385d-63e5-49d4-ab79-98abff4a73b6', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a92519bd-3998-48d1-bc1e-daf7335fc234', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8da9385d-63e5-49d4-ab79-98abff4a73b6', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
