INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('30b1e82c-e9d9-4362-a166-d942a27d2a52', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '36c47cd8-60ef-4278-adb5-c4a781dbe2f4', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
