INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29950fa7-40d6-41b7-8d5b-18243670123b', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '36c47cd8-60ef-4278-adb5-c4a781dbe2f4', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
