INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ddb3bb63-3622-453a-86bd-8751a5f230dd', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8a8fc500-f90a-40fd-ab5f-92f57c981326', 'none', 'types.detail.video_controls.none', 'Neither the custom nor the native toolbar is rendered. The consumer drives playback programmatically through the #controls slot or the exposed composable methods.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ece7e83-0f4c-4af0-9f05-74f9c2447eb6', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8a8fc500-f90a-40fd-ab5f-92f57c981326', 'custom', 'types.detail.video_controls.custom', 'The component paints its own toolbar with play/pause, scrubber, volume, captions, PIP and fullscreen buttons. The <video> element is rendered WITHOUT the native controls attribute. Default.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4be49c3-d958-4a1b-b558-2417d7891777', '2026-11-21 16:23:07.882144+00', '2026-11-21 16:23:07.882144+00', '8a8fc500-f90a-40fd-ab5f-92f57c981326', 'native', 'types.detail.video_controls.native', 'The <video> element receives the native controls attribute and the browser paints its own toolbar. Useful for AirPlay on Safari or inside Tauri shells that talk to native players.', 2, false, NULL, NULL);
